import { planTasksForRun } from './plan-question.js'
import type { Task } from '@buildaharness/harness'
import type { ILLMClient, TokenUsage, ReminderStore, ChatMessage } from '@buildaharness/runtime'
import { checkRequestAmbiguity } from './ambiguity-guard.js'
import type { AmbiguityGuardMode } from './ambiguity-guard-flag.js'
import { classifyTurnIntent, type TurnIntentClassification } from './turn-intent-classifier.js'
import { evaluateTurnPolicy, evaluateAbandonPolicy } from './turn-policy.js'
import { looksLikeCodingFact } from './contradiction-checker.js'
import { reframeTaskDescriptionWithLLM } from './decomposition-classifier.js'
import type { PlanRecord } from './plan-store.js'
import { deriveConsequentialTools, type LayerPolicyMode } from '@buildaharness/harness'
import { TOOL_EFFECT_CLASS } from './tool-effect-class.js'
import { resolveEscalationPlan, decompositionReframeEnabled } from './layer-policy-wiring.js'
import { PlanService } from './plan-service.js'
import { toHarnessTasks, toTaskRiskLevel, planTaskRiskLevel } from './task-mapping.js'
import type { AssistantTrace, AssistantTurnResult } from './assistant-types.js'

/**
 * `AUDIT_DECOMPOSITION` gate — feature-value audit (Phase C4 of the internal plan). Default
 * **ON**: the classifier's `decomposedTasks` graph and the single-task
 * `reframeTaskDescriptionWithLLM` call both shape the turn today, so an unset / empty / truthy
 * value keeps that behaviour. Set to a falsy value (`0` / `false` / `off` / `no` / `disabled`) to
 * take the single-task path: the raw user message as one `respond` task, no decomposition, no
 * reframe call. The classifier call itself is untouched (it also produces the intent/risk fields
 * every arm needs). Read at exactly one call site — the top of `resolveTasks()` below. An active
 * plan's own tasks are not decomposition and are unaffected. Same shape as
 * `semanticContradictionEnabled()` (contradiction-checker.ts).
 */
export function decompositionEnabled(env?: Record<string, string | undefined>): boolean {
  const source = env ?? (typeof process !== 'undefined' ? process.env : {})
  const raw = String(source.AUDIT_DECOMPOSITION ?? '').trim().toLowerCase()
  if (raw === '') return true
  return !['0', 'false', 'off', 'no', 'disabled'].includes(raw)
}

/**
 * The front portion of runTurn — plan-cancel-bypass detection, the classifyTurnIntent call, the
 * message-level risk-gate decision, and (via `resolveTasks`) decomposition/plan-template
 * resolution — as a pure decision-maker. Deliberately no MemoryAdapter/onTrace dependency beyond
 * what's passed as plain arguments/collaborators (PlanService, ReminderStore), so this stays
 * unit-testable without heavy mocks. Does NOT append to the transcript or call onTrace itself —
 * every variant below carries enough data for the sequencer (assistant.ts) to do both, in the
 * exact order the pre-split code did.
 */
export type TurnInterpretation =
  | {
      kind: 'bypass'
      result: AssistantTurnResult
      transcriptAppend: { user: string; assistant: string }
      planUpdatedTrace: { templateName: string | null; completionPct: number }
    }
  | { kind: 'needs_approval'; classification: TurnIntentClassification; result: AssistantTurnResult }
  /** AL3a — the request doesn't determine the action; `result` is the clarifying question, returned before anything is staged. */
  | { kind: 'needs_question'; classification: TurnIntentClassification; result: AssistantTurnResult }
  | { kind: 'proceed'; classification: TurnIntentClassification; planForCancelCheck: PlanRecord | null }

export interface ResolvedTasks {
  initialTasks: Task[]
  activePlan: PlanRecord | null
  /** Only set when a NEW plan match was attempted this turn (i.e. no active plan was already being resumed) — mirrors the original code's `else` branch, which is the only place this trace fired. */
  planClassifiedTrace?: { isCandidate: boolean; matchedTemplate: string | null }
}

export class TurnInterpreter {
  constructor(
    private readonly llmClient: ILLMClient,
    private readonly model: () => string | undefined,
    private readonly planService: PlanService,
    private readonly reminderStore: ReminderStore,
    private readonly ambiguityGuardMode: AmbiguityGuardMode = 'disabled',
    // AL8b: routes the single-task reframe LLM call through the layer policy (static ⇒ today's behaviour).
    private readonly layerPolicyMode: LayerPolicyMode = 'static',
  ) {}

  /** AL8b: decomposition-reframe policy decision; any error ⇒ today's behaviour (allowed). */
  private reframePolicyAllows(classification: { riskLevel: string; isTrivial?: boolean }, taskCount: number): boolean {
    if (this.layerPolicyMode !== 'adaptive') return true
    try {
      const plan = resolveEscalationPlan(
        this.layerPolicyMode,
        { riskLevel: toTaskRiskLevel(classification.riskLevel as never), taskCount, hasDurablePlan: false, consequentialTools: deriveConsequentialTools(Object.keys(TOOL_EFFECT_CLASS), TOOL_EFFECT_CLASS), isTrivial: classification.isTrivial },
        undefined,
      )
      return decompositionReframeEnabled(plan)
    } catch {
      return true
    }
  }

  async interpretIntent(params: {
    userMessage: string
    sessionId: string
    toolLoopWillRun: boolean
    approved: boolean
    dangerouslySkipPermissions: boolean
    onUsage: (usage: TokenUsage) => void
    /** Recent transcript, used only by the AL3a ambiguity guard so an answer to an earlier question isn't re-asked. */
    recentTranscript?: ChatMessage[]
    /** Constraints stated earlier this session; shown to the classifier so the message can lift one. */
    standingConstraints?: string[]
    /** Keyed facts already stored; shown to the classifier so it reuses their keys. */
    knownFactKeys?: { key: string; text: string }[]
  }): Promise<TurnInterpretation> {
    const { userMessage, sessionId, toolLoopWillRun, approved, dangerouslySkipPermissions, onUsage, recentTranscript, standingConstraints, knownFactKeys } = params

    // Per-task plan cancellation ("cancel the daily-budget task", "skip the research step") is
    // internal bookkeeping — it never touches anything outside this session's own plan state,
    // unlike a real-world "cancel my gym membership" — so it's handled here, before
    // classifyTurnIntent's single consolidated LLM call below ever runs: both because it's a
    // tighter, plan-aware match than a general risk gate should have to express, and because
    // short-circuiting here means a turn that's just cancelling one task doesn't spend the
    // consolidated call at all.
    const planForCancelCheck = await this.planService.loadActivePlan(sessionId)
    if (planForCancelCheck) {
      const cancelMatch = this.planService.matchTaskCancelAttempt(userMessage, planForCancelCheck)
      if (cancelMatch) {
        const updatedPlan = await this.planService.cancelPlanTask(sessionId, planForCancelCheck, cancelMatch.taskId)
        const next = this.planService.nextPendingTask(updatedPlan)
        const reply = next
          ? `Cancelled "${cancelMatch.taskDescription}". Continuing with the rest of the plan — next up: ${next.description}`
          : `Cancelled "${cancelMatch.taskDescription}". That was the last remaining task, so the plan is complete.`
        const completionPct = this.planService.planCompletionPct(updatedPlan)
        const skippedTrace: AssistantTrace = { nodeExecutionOrder: [], verificationHealth: { strength: 0, feasibility: 0 }, layerActivity: [] }
        const result: AssistantTurnResult = {
          status: 'ok',
          reply,
          riskLevel: 'LOW',
          stepsUsed: 0,
          harnessSkipped: true,
          trace: skippedTrace,
          planStatus: {
            templateName: updatedPlan.templateName,
            successCriteria: updatedPlan.successCriteria,
            completionPct,
            tasks: updatedPlan.tasks.map((t) => ({ id: t.id, description: t.description, status: t.cancelled ? 'CANCELLED' : t.status })),
          },
        }
        return {
          kind: 'bypass',
          result,
          transcriptAppend: { user: userMessage, assistant: reply },
          planUpdatedTrace: { templateName: updatedPlan.templateName, completionPct },
        }
      }
    }

    // Single consolidated LLM call replacing the former classifyRisk/classifyTriviality/
    // classifyDecompositionCandidate/isAbandonPhrase/classifyPlanningCandidate chain — see
    // turn-intent-classifier.ts.
    const classification = await classifyTurnIntent(userMessage, this.llmClient, { hasActivePlan: planForCancelCheck !== null, standingConstraints, knownFactKeys }, this.model(), onUsage)

    // Phase D3: the authoritative approval decision — recomputed from classification's own
    // riskLevel/isBulkReminderRequest signals via turn-policy.ts rather than trusted directly off
    // classification.requiresApproval (see turn-policy.ts's own doc comment for why that split
    // matters). Behaviorally identical to classification.requiresApproval today (both are derived
    // from the same two fields via the same rule), but no longer relies on that boolean surviving
    // unmodified from the classifier to this gate.
    const turnPolicy = evaluateTurnPolicy({ riskHint: classification.riskLevel, isBulkReminderRequest: classification.isBulkReminderRequest })

    // A reminder-shaped MEDIUM request stores a record immediately — detection, not action
    // gating, so it happens whether or not the rest of the turn is ultimately
    // approved/completed. v1 stores raw text with no time parsing (dueAt: null) — see
    // ReminderStore's doc comment.
    //
    // Only fires when no tool loop is coming up: whenever fileTools/webTools/shellTools is
    // configured, REMINDER_TOOLS is always offered to the model, so the model can and does call
    // create_reminder itself for the exact same message — storing the raw text here too produced
    // two records for one request. This pre-emptive store is a fallback for backends where no
    // tool loop ever runs at all, not a second insurance policy alongside one.
    //
    // turnPolicy.decision === 'REQUIRE_APPROVAL' here means this looks like a BULK reminder
    // request — must not auto-create anything until the approval gate below actually runs, or
    // this would silently create a reminder before the user ever sees the prompt.
    if (!toolLoopWillRun && classification.riskLevel === 'MEDIUM' && classification.isReminderRequest && turnPolicy.decision === 'ALLOW') {
      await this.reminderStore.create(userMessage, null)
    }

    // AL3a — ask before staging. Only consequential turns (message-level approval gate, or a
    // MEDIUM/HIGH turn that will run write/shell tools) pay for the scope check; UNKNOWN means the
    // classifier itself failed, so the check would likely fail too — leave that on the approval gate.
    // `approved` is an explicit user go-ahead on an already-shown action: never re-question it.
    if (
      this.ambiguityGuardMode === 'enabled' &&
      !approved &&
      !dangerouslySkipPermissions &&
      classification.riskLevel !== 'UNKNOWN' &&
      (turnPolicy.decision === 'REQUIRE_APPROVAL' ||
        (toolLoopWillRun && (classification.riskLevel === 'MEDIUM' || classification.riskLevel === 'HIGH')))
    ) {
      const check = await checkRequestAmbiguity(userMessage, this.llmClient, recentTranscript ?? [], this.model(), onUsage)
      if (check.ambiguous) {
        return {
          kind: 'needs_question',
          classification,
          result: { status: 'ok', reply: check.question, riskLevel: classification.riskLevel, stepsUsed: 0, harnessSkipped: true },
        }
      }
    }

    if (turnPolicy.decision === 'REQUIRE_APPROVAL' && !approved && !dangerouslySkipPermissions) {
      // Deliberately not persisted to transcript — the outcome isn't known yet (a decline never
      // calls turn() again for this gate, unlike the pendingActionId gate, which always resolves
      // via ActionApprovalService) — see the sequencer for the full reasoning.
      return {
        kind: 'needs_approval',
        classification,
        result: { status: 'needs_approval', reply: null, reason: classification.riskReason, riskLevel: classification.riskLevel },
      }
    }

    return { kind: 'proceed', classification, planForCancelCheck }
  }

  /**
   * Decomposition/plan-template resolution — only meaningful (and only ever called by the
   * sequencer) once a turn is known NOT to be trivial, since a trivial turn returns before any
   * of this would matter and must not spend buildPlanFromTemplate's LLM call for nothing.
   */
  async resolveTasks(params: {
    userMessage: string
    sessionId: string
    classification: TurnIntentClassification
    planForCancelCheck: PlanRecord | null
    onUsage: (usage: TokenUsage) => void
    /** The turn only asks about the active plan (turn-intent-classifier.ts's isPlanQuestion, routing enabled): keep the plan for display but don't let it drive the turn's tasks. */
    planQuestion?: boolean
  }): Promise<ResolvedTasks> {
    const { userMessage, sessionId, classification, planForCancelCheck, onUsage, planQuestion = false } = params
    // The single AUDIT_DECOMPOSITION read: gates both the classifier's decomposedTasks graph and
    // the reframe call below, so the OFF arm is exactly the single-task path.
    const decompose = decompositionEnabled()

    // The single-task fallback — the raw userMessage verbatim as its description, unlike
    // classifyTurnIntent's own decomposedTasks/buildPlanFromTemplate, which already ask for a
    // subject-first description. Reusing that same phrasing here keeps the "Completed: <description>"
    // belief statementsOpposed/isNegation compare against structured consistently across every
    // task-creation path.
    let initialTasks: Task[] = toHarnessTasks([{ id: 'respond', description: userMessage, depends_on: [] }], toTaskRiskLevel(classification.riskLevel))
    const decomposed = decompose ? classification.decomposedTasks : null
    if (decomposed) {
      initialTasks = toHarnessTasks(decomposed, toTaskRiskLevel(classification.riskLevel))
    }

    // Structured planning: an active plan for this session takes precedence over
    // re-classifying every turn, so an unrelated aside mid-plan doesn't get silently
    // reinterpreted as "start a new plan". classification.isAbandonRequest is only ever true
    // when planForCancelCheck (passed as context.hasActivePlan to classifyTurnIntent) was
    // non-null, so it's safe to act on unconditionally here.
    let activePlan: PlanRecord | null = planForCancelCheck
    if (activePlan && evaluateAbandonPolicy({ hasActivePlan: true, abandonHint: classification.isAbandonRequest })) {
      await this.planService.abandonPlan(sessionId, activePlan)
      activePlan = null
    }

    // P3 of the internal plan: a matched template no longer builds and
    // activates a plan directly here — assistant.ts's auto-trigger (checked earlier in runTurn,
    // before this method is ever called) routes a template match (or the general
    // needsMultiStepPlan judgment) into plan mode's exclusive drafting+approval loop instead, so
    // `classification.matchedPlanTemplate` is never non-null by the time resolveTasks runs in
    // production. This is kept as a pure observability trace (not a plan-building side effect) for
    // that reason — see PlanDraftingService.draftTurn for where template seeding actually happens
    // now.
    let planClassifiedTrace: ResolvedTasks['planClassifiedTrace']
    if (activePlan && planQuestion) {
      // A question about the plan is one ordinary turn: the plan stays as it is (still `activePlan`,
      // so the result reports its status) but its tasks are not re-run.
      initialTasks = toHarnessTasks([{ id: 'respond', description: userMessage, depends_on: [] }], toTaskRiskLevel(classification.riskLevel))
    } else if (activePlan) {
      // A failed step gets another attempt (and the reason it was rejected) rather than stranding the run.
      initialTasks = toHarnessTasks(planTasksForRun(activePlan.tasks), planTaskRiskLevel)
    } else {
      planClassifiedTrace = { isCandidate: classification.matchedPlanTemplate !== null, matchedTemplate: classification.matchedPlanTemplate }
    }

    // Gated by both looksLikeCodingFact AND riskLevel !== 'LOW' — looksLikeCodingFact alone is
    // too loose to gate a *new* LLM call on: it's a plain keyword list built for a lower-stakes
    // purpose, so common non-technical words it also happens to contain false-positive on
    // ordinary conversation. riskLevel !== 'LOW' isn't just a tighter filter — it's the actual
    // precondition for this to ever matter: harness-runtime.ts's world-model layer only writes a
    // "Completed: ..." trail belief from a single task (taskCount === 1, true here by
    // construction) when no fact was extracted from the turn *and* riskLevel !== 'LOW'.
    if (
      decompose &&
      this.reframePolicyAllows(classification, initialTasks.length) &&
      initialTasks.length === 1 &&
      initialTasks[0].id === 'respond' &&
      classification.riskLevel !== 'LOW' &&
      looksLikeCodingFact(userMessage)
    ) {
      const reframed = await reframeTaskDescriptionWithLLM(userMessage, this.llmClient, this.model(), onUsage)
      if (reframed) {
        initialTasks = toHarnessTasks([{ id: 'respond', description: reframed, depends_on: [] }], toTaskRiskLevel(classification.riskLevel))
      }
    }

    return { initialTasks, activePlan, planClassifiedTrace }
  }
}
