import { renderPlanStopNote } from './plan-question.js'
import { renderUnresolvedConstraintNote } from './constraint-check.js'
import { NOT_ACCOMPLISHED_REPLY_PREFIX } from '@buildaharness/harness'
import {
  riskSummary,
  ControlState,
  type EscalationHalt,
  type HarnessCheckpoint,
  type VerificationResult,
  type LayerActivityEvent,
  type HarnessRunResult,
} from '@buildaharness/harness'
import type { MemoryAdapter, TokenUsage } from '@buildaharness/runtime'
import { buildAnswerClaim } from './answer-claim.js'
import type { GroundingResult } from './grounding-check.js'
import type { TurnIntentClassification } from './turn-intent-classifier.js'
import type { PlanRecord } from './plan-store.js'
import { PlanService } from './plan-service.js'
import { loadGoalGraphRecord, saveGoalGraphRecord, createEmptyGoalGraphRecord, addThreadSuggestions, type GoalThread, type ThreadSuggestion } from './goal-graph-store.js'
import { syncThreadFromTaskGraph } from './goal-thread-scheduler.js'
import type { AssistantSession } from './assistant-session.js'
import type { MemoryService } from './memory-service.js'
import type { AssistantSource } from './assistant-source.js'
import type { BatchBudgetTrace } from './agent-loop.js'
import type { AssistantTrace, AssistantTurnResult } from './assistant-types.js'
import type { TraceEvent } from './trace-events.js'

/** Drops the internal `excerpt` (raw tool text, grounding-check input only) so it never reaches a result, transcript or UI. */
function publicSources(sources: AssistantSource[] | undefined): AssistantSource[] | undefined {
  return sources?.map(({ excerpt: _excerpt, ...source }) => source)
}

/**
 * AssistantTurnResult assembly for every return path — the triviality fast path, the
 * plan-pacing pause, the harness success path, and the EscalationHalt-caught path — split out of
 * runTurn in Phase 4d of the architecture remediation plan. Each method persists whatever this
 * path needs to persist (transcript, facts, plan) and returns the final result, so the sequencer
 * (assistant.ts) never has to duplicate per-path assembly logic.
 */
export class ResponseService {
  constructor(
    private readonly memoryService: MemoryService,
    private readonly session: AssistantSession,
    private readonly planService: PlanService,
    private readonly onTrace: ((event: TraceEvent) => void) | undefined,
    // Phase 5 of plans/hierarchical_goal_tree_and_steering_plan.html — INV-42 ("PAUSED preserves
    // partial state/evidence — never silently discarded on preemption"): only needed when a
    // caller resolves a `goalThreadId` (buildPausedResult/buildSuccessResult below), so this
    // stays undefined for every caller that predates goalGraphMode (same "absent means skip"
    // convention memory/agentLoop already follow in PlanDraftingService's constructor).
    private readonly memory?: MemoryAdapter,
    // R7 (Tier 1.5, plans/hierarchical_goal_tree_and_steering_plan.html) — proposes next steps for
    // a GoalThread the moment its own task evidence shows it just finished. Absent (the default for
    // every caller that never opted in, and whenever goalGraphSuggestMode is 'disabled') means no
    // proposal and no extra LLM call. Best-effort by construction: see syncGoalThreadEvidence.
    private readonly nextStepProposer?: (thread: GoalThread, onUsage: ((usage: TokenUsage) => void) | undefined, sessionId: string) => Promise<ThreadSuggestion[]>,
    // Compares a finished reply to the raw tool results behind it (grounding-check.ts) so
    // answerClaim can only say `verified` for a reply that matched them. Absent when
    // AUDIT_SEMANTIC_GROUNDING is off — buildAnswerClaim then keeps its mechanical-only meaning.
    private readonly groundingChecker?: (input: { question: string; reply: string; sources: AssistantSource[] | undefined }, onUsage: ((usage: TokenUsage) => void) | undefined) => Promise<GroundingResult>,
  ) {}

  /**
   * INV-42's concrete mechanism: mirrors the `activePlan`-based `saveAndSummarize` sync just
   * above/below each call site, but onto `threadId`'s own `GoalThread.tasks` via
   * `syncThreadFromTaskGraph` — looked up **by id**, not by `getActiveThread`, so this still
   * lands the run's evidence on a thread the Scheduler has since moved to `PAUSED` (an in-flight
   * tool call that was already running when a steering message preempted its thread runs to
   * completion per Q3's "let it finish" default, and its result must still reach the now-PAUSED
   * thread, not be silently dropped). A no-op when `memory` wasn't wired in, or the caller never
   * resolved a `threadId` — exactly today's behavior either way (INV-43).
   */
  private async syncGoalThreadEvidence(
    sessionId: string,
    threadId: string | undefined,
    taskGraphTasks: { id: string; status: string; description?: string; depends_on?: string[]; risk_level?: string }[],
    onUsage?: (usage: TokenUsage) => void,
  ): Promise<void> {
    if (!threadId || !this.memory) return
    const fsPersistence = this.session.undoWorkspace()
    const goalGraph = (await loadGoalGraphRecord(this.memory, sessionId, fsPersistence)) ?? createEmptyGoalGraphRecord()
    let updated = syncThreadFromTaskGraph(goalGraph, threadId, taskGraphTasks as { id: string; status: 'PENDING' | 'RUNNING' | 'COMPLETE' | 'FAILED' | 'BLOCKED' | 'HUMAN_REQUIRED'; description?: string; depends_on?: string[]; risk_level?: 'LOW' | 'MEDIUM' | 'HIGH' }[])

    // R7: propose next steps exactly once, on the sync that carries this thread to DONE (the
    // before/after status comparison — a thread that was already DONE never re-proposes). One
    // bounded LLM call; any failure just means no suggestions, never a failed turn. High and
    // medium confidence suggestions are persisted on the thread as advisory nodes; low confidence
    // ones are advisory for this turn only and are dropped by addThreadSuggestions.
    const before = goalGraph.threads.find((t) => t.id === threadId)
    const after = updated.threads.find((t) => t.id === threadId)
    if (this.nextStepProposer && before && after && before.status !== 'DONE' && after.status === 'DONE') {
      try {
        updated = addThreadSuggestions(updated, threadId, await this.nextStepProposer(after, onUsage, sessionId))
      } catch {
        // best-effort — the thread is still correctly DONE
      }
    }
    await saveGoalGraphRecord(this.memory, sessionId, updated, fsPersistence)
  }

  async buildTrivialResult(params: {
    sessionId: string
    transcriptKey: string
    userMessage: string
    draftReply: string
    classification: TurnIntentClassification
    sources: AssistantSource[] | undefined
    batchBudgetTrace: BatchBudgetTrace | undefined
    usageTotal: TokenUsage | undefined
    onUsage?: (usage: TokenUsage) => void
  }): Promise<AssistantTurnResult> {
    const { sessionId, transcriptKey, userMessage, draftReply, classification, sources, batchBudgetTrace, usageTotal, onUsage } = params
    await this.session.appendTranscriptMessage(sessionId, transcriptKey, { role: 'user', content: userMessage })
    await this.session.appendTranscriptMessage(sessionId, transcriptKey, { role: 'assistant', content: draftReply })
    // Phase 3 ordering constraint: recordFacts()'s entry-time consistency check must run, and its
    // contradictions must be folded into the turn's contradictionNotice, before returning — a
    // plain fact-stating message is exactly the shape most likely to hit this trivial fast path,
    // so this can't be the one path that silently drops the signal (see memory-service.ts's
    // recordFacts doc comment).
    const { contradictions } = await this.memoryService.recordFacts(sessionId, userMessage, classification.statesDurableFacts, onUsage)
    const contradictionNotice = await this.session.dedupedContradictionNotice(sessionId, [], contradictions)
    // No layer fired this turn — an empty trace rather than an absent one, so the "Why?"/"Run
    // detail" UI can still render (all 11 layer cells shown, none highlighted) instead of hiding
    // the panel outright, which read as broken rather than "skipped on purpose".
    const skippedTrace: AssistantTrace = { nodeExecutionOrder: [], verificationHealth: { strength: 0, feasibility: 0 }, layerActivity: [], batchBudget: batchBudgetTrace }
    return { status: 'ok', reply: draftReply, riskLevel: classification.riskLevel, stepsUsed: 0, harnessSkipped: true, trace: skippedTrace, sources: publicSources(sources), usage: usageTotal, contradictionNotice }
  }

  async buildPausedResult(params: {
    sessionId: string
    transcriptKey: string
    userMessage: string
    draftReply: string
    classification: TurnIntentClassification
    activePlan: PlanRecord | null
    checkpoint: HarnessCheckpoint
    lastVerification: VerificationResult | null
    layerActivity: LayerActivityEvent[]
    sources: AssistantSource[] | undefined
    batchBudgetTrace: BatchBudgetTrace | undefined
    usageTotal: TokenUsage | undefined
    onUsage?: (usage: TokenUsage) => void
    goalThreadId?: string
    /** Task id → why the completion check judged it not done, from this run; persisted on the plan. */
    taskNotes?: Record<string, string>
  }): Promise<AssistantTurnResult> {
    const { sessionId, transcriptKey, userMessage, draftReply, classification, activePlan, checkpoint, lastVerification, layerActivity, sources, batchBudgetTrace, usageTotal, onUsage, goalThreadId, taskNotes } = params

    // An intentional plan-pacing stop — not a bug. Persist the plan's current task statuses (same
    // as the success path) so the next turn's pacing/position computations start from up-to-date
    // state, and surface a plain "ready to continue?" reply instead of the harness's own
    // draft/final result.
    // R3 of the internal plan: under the one-loop flag, `draftReply` is
    // deferred (assistant.ts never precomputes it before calling harnessBridge.run() when a
    // caller-supplied proposer is in play — see agent-loop.ts's createOneLoopProposer) — it stays
    // `''` unless a plan-pacing pause happens to fire after the harness-driven proposer has
    // already produced a real answer for the just-completed task. `checkpoint.progress.finalResult`
    // is exactly that answer: harness-runtime.ts's driveMainLoop sets `ctx.finalResult =
    // execResult.output` right after a task completes, strictly before shouldPause is ever
    // checked, so by the time a pause can fire at all, finalResult already holds that task's real
    // output text. This is also safe (and a no-op) on the flag-OFF path: there,
    // `toolExecutors.default` is always `() => draftReply` for every task, so finalResult always
    // equals draftReply already — reading it here instead changes nothing observable (INV-19),
    // it just also covers the flag-ON case where draftReply alone would otherwise be empty. Same
    // `typeof ... === 'string' ? ... : draftReply` fallback shape buildSuccessResult below already
    // uses for the exact same reason.
    const reportedReply = typeof checkpoint.progress.finalResult === 'string' ? checkpoint.progress.finalResult : draftReply

    let planStatus: AssistantTurnResult['planStatus']
    let reply = 'Paused.'
    let pausedNote: string | undefined
    if (activePlan) {
      const { plan: updatedPlan, planStatus: ps } = await this.planService.saveAndSummarize(sessionId, activePlan, checkpoint.runState.taskGraph.tasks, taskNotes)
      planStatus = ps
      this.onTrace?.({ kind: 'plan_updated', templateName: updatedPlan.templateName, completionPct: ps.completionPct })
      const next = this.planService.nextPendingTask(updatedPlan)
      const pacingNote = next
        ? `Ready to continue with: ${next.description}? (reply to proceed)`
        : 'All plan steps have run — let me know if you want anything else.'
      // draftReply (the LLM's own answer to this turn, computed and streamed to the caller via
      // onToken well before the harness ever ran) must not be dropped here. It was already shown
      // live to a streaming caller (cli.ts's streamedAnyTokens path prints nothing further once
      // tokens have streamed, trusting that whatever gets returned/persisted below matches what's
      // already on screen), so persisting only the pacing note would leave the transcript — and
      // therefore /export, /search, and every later turn's LLM context — recording a reply the
      // user never actually saw, while silently discarding the one they did.
      reply = reportedReply.trim() ? `${reportedReply}\n\n${pacingNote}` : pacingNote
      pausedNote = pacingNote
    }
    // Land this run's task evidence on the goal thread the turn was resolved to — for every turn,
    // not only a plan-driven one. This used to sit inside the `if (activePlan)` block above, so an
    // ordinary turn never synced to its thread (and no thread could ever reach DONE).
    await this.syncGoalThreadEvidence(sessionId, goalThreadId, checkpoint.runState.taskGraph.tasks, onUsage)

    await this.session.appendTranscriptMessage(sessionId, transcriptKey, { role: 'user', content: userMessage })
    await this.session.appendTranscriptMessage(sessionId, transcriptKey, { role: 'assistant', content: reply })
    // Phase 3 ordering constraint — see buildTrivialResult's comment: recordFacts() must run, and
    // its contradictions must be folded in, before contradictionNotice is finalized below.
    const { contradictions } = await this.memoryService.recordFacts(sessionId, userMessage, classification.statesDurableFacts, onUsage)
    const contradictionNotice = await this.session.dedupedContradictionNotice(sessionId, layerActivity, contradictions)

    const trace: AssistantTrace = {
      nodeExecutionOrder: checkpoint.progress.nodeExecutionOrder,
      verificationHealth: { ...checkpoint.runState.diagnostics.verification_health },
      layerActivity,
      batchBudget: batchBudgetTrace,
    }

    const answerClaim = buildAnswerClaim({
      evidence: checkpoint.runState.evidenceStore.observations,
      verification: lastVerification,
      contradicted: contradictionNotice !== undefined,
      verificationHealth: trace.verificationHealth,
      // The substantive answer, not the pacing note appended to it.
      grounding: await this.groundingChecker?.({ question: userMessage, reply: reportedReply, sources }, onUsage),
    })

    return {
      status: 'ok',
      reply,
      riskLevel: classification.riskLevel,
      controlState: {
        riskState: riskSummary(new ControlState(checkpoint.runState.controlState)),
        escalationReason: checkpoint.runState.controlState.escalation_reason,
      },
      stepsUsed: checkpoint.progress.stepsUsed,
      harnessSkipped: false,
      trace,
      sources: publicSources(sources),
      planStatus,
      contradictionNotice,
      answerClaim,
      pausedNote,
      usage: usageTotal,
    }
  }

  async buildSuccessResult(params: {
    sessionId: string
    transcriptKey: string
    userMessage: string
    draftReply: string
    classification: TurnIntentClassification
    activePlan: PlanRecord | null
    result: HarnessRunResult
    lastVerification: VerificationResult | null
    layerActivity: LayerActivityEvent[]
    sources: AssistantSource[] | undefined
    batchBudgetTrace: BatchBudgetTrace | undefined
    usageTotal: TokenUsage | undefined
    onUsage?: (usage: TokenUsage) => void
    goalThreadId?: string
    /** Task id → why the completion check judged it not done, from this run; persisted on the plan. */
    taskNotes?: Record<string, string>
  }): Promise<AssistantTurnResult> {
    const { sessionId, transcriptKey, userMessage, draftReply, classification, activePlan, result, lastVerification, layerActivity, sources, batchBudgetTrace, usageTotal, onUsage, goalThreadId, taskNotes } = params

    const stepsUsed = result.stepsUsed
    const controlState = {
      riskState: riskSummary(new ControlState(result.initResult.controlState)),
      escalationReason: result.initResult.controlState.escalation_reason,
    }
    const trace: AssistantTrace = {
      nodeExecutionOrder: result.nodeExecutionOrder,
      verificationHealth: { ...result.initResult.diagnostics.verification_health },
      layerActivity,
      batchBudget: batchBudgetTrace,
    }

    const baseReply = typeof result.finalResult === 'string' ? result.finalResult : draftReply
    // A plan run that stopped on a rejected step says so, unless the reply already is that news.
    const stopNote = activePlan && !baseReply.startsWith(NOT_ACCOMPLISHED_REPLY_PREFIX) ? renderPlanStopNote(activePlan, taskNotes) : ''
    const reply = `${baseReply}${stopNote}${renderUnresolvedConstraintNote(result.unresolvedConstraintViolations)}`

    await this.session.appendTranscriptMessage(sessionId, transcriptKey, { role: 'user', content: userMessage })
    await this.session.appendTranscriptMessage(sessionId, transcriptKey, { role: 'assistant', content: reply })
    // Phase 3 ordering constraint — see buildTrivialResult's comment: recordFacts() must run, and
    // its contradictions must be folded in, before contradictionNotice is finalized below.
    const { contradictions } = await this.memoryService.recordFacts(sessionId, userMessage, classification.statesDurableFacts, onUsage)
    const contradictionNotice = await this.session.dedupedContradictionNotice(sessionId, layerActivity, contradictions)

    // Write the harness's resulting task statuses back onto the plan only on this success path —
    // an aborted/errored turn leaves the stored plan as-is, so a crash mid-turn can't corrupt
    // plan state; the plan simply gets resumed and re-driven next turn instead.
    let planStatus: AssistantTurnResult['planStatus']
    if (activePlan) {
      const { plan: updatedPlan, planStatus: ps } = await this.planService.saveAndSummarize(sessionId, activePlan, result.initResult.taskGraph.tasks, taskNotes)
      planStatus = ps
      this.onTrace?.({ kind: 'plan_updated', templateName: updatedPlan.templateName, completionPct: ps.completionPct })
    }
    // See the paused path: the thread sync applies to every turn, not only a plan-driven one.
    await this.syncGoalThreadEvidence(sessionId, goalThreadId, result.initResult.taskGraph.tasks, onUsage)

    const answerClaim = buildAnswerClaim({
      evidence: result.initResult.evidenceStore.observations,
      verification: lastVerification,
      contradicted: contradictionNotice !== undefined,
      verificationHealth: trace.verificationHealth,
      grounding: await this.groundingChecker?.({ question: userMessage, reply, sources }, onUsage),
    })

    return { status: 'ok', reply, riskLevel: classification.riskLevel, controlState, stepsUsed, harnessSkipped: false, trace, sources: publicSources(sources), planStatus, contradictionNotice, answerClaim, usage: usageTotal }
  }

  async buildEscalatedResult(params: {
    sessionId: string
    transcriptKey: string
    userMessage: string
    err: EscalationHalt
    classification: TurnIntentClassification
  }): Promise<AssistantTurnResult> {
    const { sessionId, transcriptKey, userMessage, err, classification } = params
    await this.session.appendTranscriptMessage(sessionId, transcriptKey, { role: 'user', content: userMessage })
    // A Trajectory Supervisor ASK_USER (S3) carries a structured question (+ optional
    // choices) — surface that verbatim rather than the generic missing_info join, so the
    // caller shows the actual question. Falls back to missing_info / the bare reason.
    const q = err.blocker.question
    const reason = q
      ? err.blocker.options?.length
        ? `${q} (${err.blocker.options.join(' / ')})`
        : q
      : err.blocker.missing_info.join('; ') || err.blocker.reason
    this.onTrace?.({ kind: 'escalation', reason })
    // stepsUsed is always 0 here: the only place the pre-split code ever assigned a nonzero
    // stepsUsed before this catch ran is the harness success path, which is now fully inside
    // HarnessBridge.run() — this catch is only reachable when EscalationHalt propagated out of
    // that call (or out of code before it), so stepsUsed was never advanced past its initial 0.
    return { status: 'escalated', reply: null, reason, riskLevel: classification.riskLevel, stepsUsed: 0 }
  }
}
