export type ToolLoopResult =
  | { kind: 'final'; content: string; sources: AssistantSource[]; batchBudget?: BatchBudgetTrace }
  | { kind: 'needs_approval'; reason: string; pendingActionId: string; pendingActionKind: 'write' | 'shell' | 'email' | 'batch' }
  | { kind: 'escalated'; reason: string }

/**
 * R2 of the internal plan: thrown by a harness-driven proposer
 * (createHarnessProposer, below) when runToolIterationStep produces a 'needs_approval' or
 * 'escalated' ToolLoopResult — the harness's own execute() rethrows anything satisfying
 * isHarnessPauseSignal unexamined (no SYSTEM_ERROR evidence, no task-FAILED transition), so this
 * is never misclassified as a tool failure. Carries the original ToolLoopResult so the eventual
 * catcher (assistant.ts's runTurn, alongside its existing `catch (err) { if (err instanceof
 * EscalationHalt) ... }` branch — see R3) can build the exact same needs_approval/escalated
 * AssistantTurnResult it already builds from a flag-OFF ToolLoopResult, without re-deriving it.
 */
export class OneLoopPause extends Error implements HarnessPauseSignal {
  readonly __harnessPause = true as const
  constructor(
    readonly result: Extract<ToolLoopResult, { kind: 'needs_approval' | 'escalated' }>,
    /**
     * P10 of the internal plan: the plan task (if any) that was RUNNING
     * — i.e. whichever task `execute()` was calling this proposer for — when `result` was
     * produced, threaded from `ToolExecutorContext.currentTaskId`. Lets the catcher
     * (assistant.ts's `buildToolLoopPauseResult`) check INV-36's trust condition without
     * re-deriving "which task was this" from anything else. `undefined` for the batch proposer's
     * own confirmation-gate throw (not a write/shell/email action, so trust mode never applies to
     * it) and for any pre-P10 construction.
     */
    readonly currentTaskId?: string,
  ) {
    super(result.reason)
    this.name = 'OneLoopPause'
  }
}

// Batch-research tuning constants (dynamic tool-call budget for batch research tasks): a
// self-calibrating alternative to the flat maxSteps cap for the one task shape that needs it —
// an explicit list of N similar lookup targets in one turn. See
// the internal plan for the reasoning behind each value.
const BATCH_PROBE_ITEM_CAP = 10 // generous fixed cap for the probe items, before calibration exists yet
const BATCH_PER_ITEM_FLOOR = 2 // never project a per-item budget below this — a cheap probe item can't starve the rest
const BATCH_SLACK_FACTOR = 1.4 // headroom multiplier over the calibrated average
const BATCH_LARGE_PROJECTION_THRESHOLD = 25 // a projection above this needs confirmation before spending it
const BATCH_ABSOLUTE_TURN_CEILING = 40 // hard stop regardless of how favorable calibration looks
const BATCH_DEAD_END_WINDOW = 3 // consecutive dead_end web_search/fetch_url results (see classifyToolYield) before an item's sub-loop gives up early instead of spending its whole per-item budget on a dead page

const INVESTIGATION_WALK_CAP = 20 // hard ceiling on a supervisor investigation's total tool calls, regardless of req.budget
const INVESTIGATION_WALK_MAX_DEPTH = 3 // how many directory levels the workspace walk descends

/** Per-item calibration inputs — see nextItemBudget. */
export interface BatchBudgetState {
  callsPerItemHistory: number[]
  perItemFloor: number
  slackFactor: number
  absoluteTurnCeiling: number
}

/**
 * Drops one min and one max before averaging once there are enough samples for that to be
 * meaningful (fewer than 3 just averages plain) — so a single unusually cheap or expensive item
 * can't swing the projection to either extreme on its own.
 */
export function trimmedAverage(counts: number[]): number {
  if (counts.length === 0) return 0
  if (counts.length < 3) return counts.reduce((sum, c) => sum + c, 0) / counts.length
  const sorted = [...counts].sort((a, b) => a - b)
  const trimmed = sorted.slice(1, -1)
  return trimmed.reduce((sum, c) => sum + c, 0) / trimmed.length
}

/** Budget for the next item to resolve — floored so a suspiciously cheap item can't starve the
 * rest, with slack headroom on top of the calibrated average. */
export function nextItemBudget(state: BatchBudgetState): number {
  const average = Math.max(state.perItemFloor, trimmedAverage(state.callsPerItemHistory))
  return Math.ceil(average * state.slackFactor)
}

/**
 * One batch item's outcome from its own per-item sub-loop (see resolveBatchItem). `exhausted`
 * means the sub-loop ran out of its budget without the model producing a final answer for this
 * item. `status` distinguishes *why* a non-'found' outcome happened: 'not_found' covers both the
 * item-scoped dead-end window tripping early (BATCH_DEAD_END_WINDOW consecutive dead_end tool
 * results) and a needs_approval bail-out; 'truncated_while_productive' means the budget ran out
 * while the trailing window was still turning up plausibly-relevant content.
 */
export interface BatchItemResolution {
  item: string
  content: string
  callsUsed: number
  exhausted: boolean
  status: 'found' | 'not_found' | 'truncated_while_productive'
  sources: AssistantSource[]
}

/**
 * Persisted across the confirmation round trip (see runBatchToolLoop's confirmation gate and
 * ActionApprovalService.resolvePendingBatchConfirmation) so approving resumes with the probe
 * items' real results intact instead of re-probing them, and declining can still return those
 * real results instead of discarding them.
 */
export interface BatchPendingState {
  userMessage: string
  systemPrompt: string
  sessionId: string
  probedResults: BatchItemResolution[]
  remainingItems: string[]
  /** The projection computed at the confirmation gate — carried across the round trip so the
   * resume/decline paths can report the same number in the batch trace instead of re-deriving
   * it (or leaving it absent) after the fact. */
  projectedTotal: number
}

/**
 * Present only when the batch-research path (batch-list-detector.ts / runBatchToolLoop) drove
 * this turn — absent otherwise, same "absent when unused" convention as sources/usage. Turns
 * `should we raise the ceiling/floor/slack factor` from a guess into a measurement.
 */
export interface BatchBudgetTrace {
  itemCount: number
  callsPerItemHistory: number[]
  projectedTotal: number
  totalCallsUsed: number
  perItemOutcomes: { item: string; status: 'found' | 'not_found' | 'truncated_while_productive'; callsUsed: number }[]
}

/** Builds a batch trace from a batch turn's resolved items — shared by runBatchToolLoop's direct
 * path and both resolvePendingBatchConfirmation outcomes (see ActionApprovalService). */
export function buildBatchBudgetTrace(
  itemCount: number,
  projectedTotal: number,
  resolutions: BatchItemResolution[],
): BatchBudgetTrace {
  return {
    itemCount,
    callsPerItemHistory: resolutions.map((r) => r.callsUsed),
    projectedTotal,
    totalCallsUsed: resolutions.reduce((sum, r) => sum + r.callsUsed, 0),
    perItemOutcomes: resolutions.map((r) => ({ item: r.item, status: r.status, callsUsed: r.callsUsed })),
  }
}

// Some OpenAI-compatible providers/models (observed live: OpenRouter's z-ai/glm-5.2) don't
// reliably populate the structured tool_calls field even when they intend to call a tool —
// they emit their own inline pseudo-XML tool-call syntax as plain content instead (e.g.
// `<tool_call>web_search<arg_key>query</arg_key><arg_value>...</arg_value></tool_call>`).
// parseToolCalls (openai-compatible-client.ts) only ever reads the structured field, so that
// content would otherwise look like an ordinary "no more tool calls" final answer and get
// shown to the user as raw tags instead of a real reply. Detected below and never surfaced.
//
// The second alternative is a generic backstop for any model's own special-token tool-call
// convention that openai-compatible-client.ts's parseLeakedToolCallSyntax couldn't recover
// (e.g. an invoked tool name that didn't match anything actually registered — observed live:
// deepseek/deepseek-v4-flash-0731 leaking a fullwidth-vertical-bar-delimited
// `<｜DSML｜tool_calls>`/`<｜DSML｜invoke name="shell">` block for a "shell" tool that doesn't
// exist here, the real one being "run_shell_command"). That U+FF5C-delimited tag shape is
// vanishingly unlikely in ordinary prose, so matching it generically — regardless of the
// namespace token between the bars — catches other models' variants of the same failure mode
// without needing a new case added here each time.
const UNPARSED_TOOL_CALL_PATTERN = /<tool_call>|<\/?｜[^｜<>]{1,32}｜(?:tool_calls?|invoke|parameter)\b/i

// Exported so any other call site that takes a model's plain-text reply at face value can
// apply the same guard — action-approval-service.ts's post-execution synthesis call is the
// first such case: it uses callChatSync (no tools, no callChatStructured recovery/retry
// machinery at all), so without this it has zero protection against exactly the same leaked
// tool-call text this guards the tool-calling loop against.
export function looksLikeUnparsedToolCall(content: string): boolean {
  return UNPARSED_TOOL_CALL_PATTERN.test(content)
}

/**
 * Builds the shell approval prompt text shared by both the claude-cli backend's `__staged_action`
 * path and the proxy backend's direct executeShellTool path — one function, so the
 * commandMayLeaveWorkspace heads-up applies identically regardless of backend. See
 * commandMayLeaveWorkspace's doc comment (shell-tools.ts) for exactly what it does and doesn't
 * catch.
 */
function shellApprovalReason(command: string, cwd: string): string {
  const base = `Proposes running: ${command}\n  (cwd: ${cwd})`
  if (!commandMayLeaveWorkspace(command)) return base
  return (
    `${base}\n  [Warning: this command references a path outside its working directory — unlike file writes, ` +
    'shell commands are not filesystem-sandboxed once approved; approval is the only gate.]'
  )
}

/**
 * Bounded ReAct loop plus the batch-research sub-loop — the "actually call the model and its
 * tools" half of PersonalAssistant, split out in Phase 4d of the architecture remediation plan.
 * Owns tool-control-plane enforcement (checkToolPolicy, below) as part of the same loop it gates,
 * per Phase 4's design: a deterministic, harness-state-informed check before each call executes,
 * not just advisory classification checked after the fact.
 */
/** See createOneLoopProposer's maxIterations doc comment. */
const RECOVERY_HEADROOM = 4

export class AgentLoop {
  constructor(
    private readonly memory: MemoryAdapter,
    private readonly llmClient: ILLMClient,
    private readonly model: () => string | undefined,
    private readonly fileTools: FileToolsContext | undefined,
    private readonly webTools: WebToolsContext | undefined,
    private readonly shellTools: ShellToolsContext | undefined,
    private readonly actionTools: ActionToolsContext | undefined,
    private readonly reminderStore: ReminderStore,
    private readonly maxSteps: number,
    private readonly onTrace: ((event: TraceEvent) => void) | undefined,
    private readonly onDebugLog: ((entry: DebugLogEntry) => void) | undefined,
  ) {}

  /**
   * Phase 4c: builds one fresh, turn-scoped live ControlState (tool-control-plane.ts), seeded
   * with the same tool-name list runToolLoop/resolveBatchItem already build internally — kept
   * here rather than in the sequencer (assistant.ts) so the caller never needs to re-import
   * FILE_TOOLS/WEB_TOOLS/SHELL_TOOLS/REMINDER_TOOLS just to construct this; AgentLoop already
   * privately owns which tools are configured. Call once per turn (when a tool loop will run)
   * and thread the result through runToolLoop/runBatchToolLoop so it's shared across every tool
   * call the turn makes, including across batch items.
   */
  createControlPlaneState(): TurnControlPlaneState {
    const toolNames = [
      ...(this.fileTools ? FILE_TOOLS : []),
      ...(this.webTools ? WEB_TOOLS : []),
      ...(this.shellTools ? SHELL_TOOLS : []),
      ...(this.actionTools ? ACTION_TOOLS : []),
      ...REMINDER_TOOLS,
      ...this.recallTools(),
    ].map((tool) => tool.name)
    // AUDIT_CONTROL_STATE_TOOL_POLICY (feature-value audit, eval-only): the one read site.
    return createTurnControlPlaneState(toolNames, { pinNormal: !controlStateToolPolicyEnabled() })
  }

  /**
   * R2 of the internal plan: builds the real toolExecutors['default']
   * entry HarnessBridge.run() swaps in when the one-loop flag is enabled — a proposer that calls
   * runToolIterationStep once per driveMainLoop iteration and translates its discriminated result
   * into the primitives D0/D1 already built: a plain return (status 'continue', no output yet) for
   * `{ done: false }`, the final answer text for a `{ done: true, result: { kind: 'final' } }`
   * step, or a thrown OneLoopPause for `needs_approval`/`escalated` — never a thrown plain Error,
   * so execute() never misclassifies this as a tool failure.
   *
   * Control-plane state: the proposer holds one real, turn-scoped `TurnControlPlaneState`
   * (`createControlPlaneState`, the exact object the flag-OFF flat path threads through
   * `runToolLoop`) for its whole lifetime — so `runToolIterationStep`'s `recordToolOutcome` has
   * real evidence/worldModel/diagnostics/failureDiagnostics stores to write each dispatched call's
   * outcome into, and same-turn tool-failure-pattern gating behaves identically to flag-OFF. On
   * top of that, the harness's own live per-iteration `toolCtx.controlState` is pinned onto that
   * state at the start of every iteration as the gate's floor (D2's "one composition, not two"
   * intent): a harness DENY / HUMAN_REQUIRED escalation is honored by `checkToolPolicy` before the
   * iteration's first call executes. `recordToolOutcome` re-resolves `.controlState` from the
   * turn-local stores after each recorded outcome — that only ever escalates further (8+ same-turn
   * failures) and `evaluateToolPolicy` ignores `execution_mode`, so it never downgrades a harness
   * escalation that would have mattered.
   */
  createHarnessProposer(input: {
    messages: ChatMessage[]
    tools: ToolDefinition[]
    sessionId: string
    userMessage: string
    maxIterations: number
    sources: AssistantSource[]
    onToken?: (token: string) => void
    onToolStep?: (step: AssistantToolStep) => void
    onUsage?: (usage: TokenUsage) => void
    riskHint?: TurnIntentClassification['riskLevel']
    /**
     * Mid-turn steering (goalGraphMode): messages the user sent while this turn runs that the
     * scope×urgency classifier judged apply to the answer being produced right now. Called once
     * per iteration, immediately before the LLM call; anything returned is spliced in as a user
     * turn so the model itself applies it — no lexical matching, unlike the harness's
     * caller-constraint output contract.
     */
    takeSteeringNotes?: () => string[]
    /**
     * Plan steps: the instruction to give the model when the harness starts working on `taskId`, or
     * undefined for a task that is just "answer the user's message" (every ordinary turn). Sent once per
     * task; the step's final answer is then kept in the conversation so a later step can build on it.
     */
    stepInstruction?: (taskId: string) => string | undefined
    /**
     * True while the harness is running several subtasks that all stand for ONE answer to the user's
     * message (an ordinary decomposed turn, not a plan). The first subtask to finish produces the answer;
     * the rest reuse it instead of asking the model the same question again. A task the harness runs a
     * second time (a retry after a rejection) gets a fresh call, never the answer that was rejected.
     */
    shareAnswer?: () => boolean
  }): (toolCtx: ToolExecutorContext) => Promise<unknown> {
    let dispatchedAnyToolCall = false
    const instructedSteps = new Set<string>()
    let sharedOutput: string | undefined
    const servedTaskIds = new Set<string>()
    let iteration = 0
    // One real, turn-scoped live ControlState for the whole proposer (= the whole turn) — see this
    // method's doc comment. recordToolOutcome dereferences state.evidenceStore, so this must be a
    // real createControlPlaneState() object, never a synthetic { controlState }-only wrapper.
    const controlPlaneState = this.createControlPlaneState()
    const seenInvestigationObs = new Set<string>()
    // AUDIT_SEMANTIC_SOURCE_RELIABILITY: the single read site. The sources are weighed at most once per
    // turn, and an answer that did not weigh them is revised at most once.
    const weighSources = optInLayerEnabled('source_reliability', sourceReliabilityEnabled(), this.optInPlan)
    let sourcesWeighed = false
    // The last answer this proposer produced — a reviewer revision asks for a new one, so the model has to see the old one.
    let lastFinalContent: string | undefined

    const proposer = async (toolCtx: ToolExecutorContext): Promise<unknown> => {
      const sharing = input.shareAnswer?.() === true && toolCtx.currentTaskId !== undefined
      if (sharing && sharedOutput !== undefined) {
        if (servedTaskIds.has(toolCtx.currentTaskId!)) {
          // The same task again means the answer was not accepted: ask the model afresh.
          sharedOutput = undefined
          servedTaskIds.clear()
        } else {
          servedTaskIds.add(toolCtx.currentTaskId!)
          return { __harnessExecutionStatus: 'complete', output: sharedOutput }
        }
      }

      if (iteration >= input.maxIterations) {
        // A genuine harness-level failure (not a pause/approval) — see execute.ts's
        // isHarnessPauseSignal special-case, which used to make this throw bypass
        // recordFailure()/rollbackAndReplan() entirely, leaving failure_match structurally
        // unreachable from a real turn (the layer_conversations audit's finding). Reset to 0
        // (not left at the ceiling) so a requeued retry (see rollback-replan.ts's
        // failureModeSwitch requeue) gets a genuine fresh per-attempt budget instead of
        // immediately re-tripping this same check on its very first call.
        iteration = 0
        return {
          __harnessExecutionStatus: 'failed',
          // Not a broken tool or model call: retrying the same task under a new strategy would run the same loop again.
          __harnessFailureKind: 'exhausted',
          error: `Tool loop exceeded ${input.maxIterations} iterations without producing a final answer.`,
        }
      }
      iteration++

      // Trajectory Supervisor GATHER_EVIDENCE (S8) — the proposer's `messages` array is
      // otherwise fixed for the whole turn, so investigation findings merged into the
      // WorldModel by resolveGatherEvidence would never reach the model. Splice any new
      // `supervisor_investigation` observations in as a user turn before this iteration's
      // call, so a re-queued task (S8 lever 1) actually re-answers over the new evidence.
      const freshFindings = (toolCtx.worldModel?.observations ?? []).filter(
        (o) => o.source === 'supervisor_investigation' && !seenInvestigationObs.has(o.id),
      )
      if (freshFindings.length > 0) {
        for (const o of freshFindings) seenInvestigationObs.add(o.id)
        input.messages.push({
          role: 'user',
          content: `[trajectory-supervisor investigation findings — read-only evidence gathered because the run had stalled]\n${freshFindings.map((o) => o.content).join('\n\n')}`,
        })
      }

      const stepInstruction = toolCtx.currentTaskId ? input.stepInstruction?.(toolCtx.currentTaskId) : undefined
      if (stepInstruction && toolCtx.currentTaskId && !instructedSteps.has(toolCtx.currentTaskId)) {
        instructedSteps.add(toolCtx.currentTaskId)
        input.messages.push({ role: 'user', content: stepInstruction })
        // The per-attempt iteration budget is per step: it otherwise counts across the whole turn, so a
        // long plan of tool-using steps would trip it partway through for no fault of the step in hand.
        iteration = 1
      }

      const allNotes = input.takeSteeringNotes?.() ?? []
      const reviewNotes = allNotes.filter((n) => n.startsWith(REVIEW_NOTE_PREFIX)).map((n) => n.slice(REVIEW_NOTE_PREFIX.length))
      const recoveryNotes = allNotes.filter((n) => n.startsWith(RECOVERY_NOTE_PREFIX)).map((n) => n.slice(RECOVERY_NOTE_PREFIX.length))
      const hypothesisNotes = allNotes.filter((n) => n.startsWith(HYPOTHESIS_NOTE_PREFIX)).map((n) => n.slice(HYPOTHESIS_NOTE_PREFIX.length))
      const revisionNotes = allNotes.filter((n) => n.startsWith(REVISION_NOTE_PREFIX)).map((n) => n.slice(REVISION_NOTE_PREFIX.length))
      const steeringNotes = allNotes.filter((n) => !n.startsWith(REVIEW_NOTE_PREFIX) && !n.startsWith(RECOVERY_NOTE_PREFIX) && !n.startsWith(HYPOTHESIS_NOTE_PREFIX) && !n.startsWith(REVISION_NOTE_PREFIX))
      if (steeringNotes.length > 0) {
        input.messages.push({
          role: 'user',
          content: `[the user sent the following while you were working on the request above — apply it to your answer]\n${steeringNotes.map((n) => `- ${n}`).join('\n')}`,
        })
      }
      for (const body of revisionNotes) {
        if (lastFinalContent !== undefined) input.messages.push({ role: 'assistant', content: lastFinalContent })
        input.messages.push({ role: 'user', content: revisionContextMessage(body) })
      }
      for (const body of hypothesisNotes) {
        input.messages.push({ role: 'user', content: hypothesisContextMessage(body) })
      }
      if (reviewNotes.length > 0) {
        input.messages.push({
          role: 'user',
          content: `[a pre-check found the request above may conflict with something the user told you earlier — say so plainly in your answer (flag it, or ask how to proceed) rather than silently going along with it]\n${reviewNotes.map((n) => `- ${n}`).join('\n')}`,
        })
      }
      if (recoveryNotes.length > 0) {
        input.messages.push({
          role: 'user',
          content: `[the previous attempt just failed]\n${recoveryNotes.map((n) => `- ${n}`).join('\n')}`,
        })
      }

      // Fold the harness's own live per-iteration ControlState in as a gate floor for this
      // iteration (see doc comment), taking whichever of it and the turn-local accumulated state
      // (which recordToolOutcome re-resolves from this turn's prior tool-call outcomes) is more
      // restrictive — an overwrite here would let a fresh harness ALLOW silently erase a DENY
      // this turn's own repeated tool failures already earned (Phase 4c's same-turn
      // failure-pattern gate).
      if (toolCtx.controlState && !controlPlaneState.pinNormal) {
        controlPlaneState.controlState = moreRestrictiveControlState(controlPlaneState.controlState, toolCtx.controlState)
      }

      const step = await this.runToolIterationStep(
        input.messages, input.tools, input.sessionId, input.userMessage, input.sources, dispatchedAnyToolCall,
        input.onToken, input.onToolStep, input.onUsage, undefined, input.riskHint ?? 'LOW', controlPlaneState,
      )

      if (!step.done) {
        dispatchedAnyToolCall = step.dispatchedAnyToolCall
        return { __harnessExecutionStatus: 'continue' }
      }

      if (step.result.kind === 'final' && weighSources && !sourcesWeighed) {
        // Under claude-cli the tool loop runs inside the subprocess, so no source note can be spliced in
        // before the answer exists; the sources are weighed after it instead, and an answer that leaned on a
        // less reliable one is asked for again once with the assessment in front of the model.
        const weighing = await assessSourceReliability(
          { question: input.userMessage, sources: input.sources, reply: step.result.content },
          this.llmClient, this.model(), input.onUsage,
        )
        if (weighing) {
          sourcesWeighed = true
          // Both evidence stores carry the judgment: the harness's (what answerClaim reads) and this
          // turn's own (what the tool-control plane reasons over).
          if (weighing.assessments.length > 0) {
            recordSourceAssessments(controlPlaneState.evidenceStore, weighing.assessments)
            if (typeof toolCtx.evidenceStore?.addObservation === 'function') recordSourceAssessments(toolCtx.evidenceStore, weighing.assessments)
          }
          if (!weighing.weighed) {
            input.messages.push({ role: 'assistant', content: step.result.content })
            input.messages.push({ role: 'user', content: renderSourceNote(weighing) })
            return proposer(toolCtx)
          }
        }
      }

      if (step.result.kind === 'final') {
        lastFinalContent = step.result.content
        // A plan step's answer is part of the conversation the next step continues from.
        if (stepInstruction) input.messages.push({ role: 'assistant', content: step.result.content })
        if (sharing) {
          sharedOutput = step.result.content
          servedTaskIds.clear()
          servedTaskIds.add(toolCtx.currentTaskId!)
        }
        return { __harnessExecutionStatus: 'complete', output: step.result.content }
      }

      throw new OneLoopPause(step.result, toolCtx.currentTaskId)
    }
    return proposer
  }

  /**
   * R3 of the internal plan: the wiring-level counterpart to
   * `createHarnessProposer` above — builds the same `messages`/`tools` shape `runToolLoop` builds
   * (system prompt + transcript + user message; whichever of FILE_TOOLS/WEB_TOOLS/SHELL_TOOLS/
   * ACTION_TOOLS/REMINDER_TOOLS are configured) so `assistant.ts`'s `runTurn` doesn't need to
   * duplicate that list-building just to wire the flag-ON path, and caps iterations at
   * `this.maxSteps` — the same cap `runToolLoop` applies — rather than something the caller has to
   * choose. Returns the mutable `sources` array threaded into the proposer so the caller can read
   * back whatever got pushed to it once the harness run using this proposer has finished (mirrors
   * `ToolLoopResult`'s `sources` field on the flag-OFF path).
   */
  createOneLoopProposer(
    sessionId: string,
    transcript: ChatMessage[],
    userMessage: string,
    systemPrompt: string,
    onToken?: (token: string) => void,
    onToolStep?: (step: AssistantToolStep) => void,
    onUsage?: (usage: TokenUsage) => void,
    riskHint: TurnIntentClassification['riskLevel'] = 'LOW',
    takeSteeringNotes?: () => string[],
    stepInstruction?: (taskId: string) => string | undefined,
    shareAnswer?: () => boolean,
  ): { proposer: (toolCtx: ToolExecutorContext) => Promise<unknown>; sources: AssistantSource[] } {
    const tools = [
      ...(this.fileTools ? FILE_TOOLS : []),
      ...(this.webTools ? WEB_TOOLS : []),
      ...(this.shellTools ? SHELL_TOOLS : []),
      ...(this.actionTools ? ACTION_TOOLS : []),
      ...REMINDER_TOOLS,
      ...this.recallTools(),
    ]
    const messages: ChatMessage[] = [
      { role: 'system', content: systemPrompt },
      ...transcript,
      { role: 'user', content: userMessage },
    ]
    const sources: AssistantSource[] = []
    const proposer = this.createHarnessProposer({
      messages, tools, sessionId, userMessage,
      // Per-attempt budget, smaller than the harness's own outer step ceiling
      // (harness-bridge.ts's max_steps) on purpose — see rollback-replan.ts's
      // requeueLeafOnLocal/failureModeSwitch. A normal turn (1-4 tool calls) never gets close,
      // so this changes nothing for the common case; it exists to give a genuinely stuck
      // attempt real headroom under the outer ceiling for one recovery-driven retry.
      //
      // Reserves a fixed RECOVERY_HEADROOM (not a fraction of this.maxSteps): tool-control-
      // plane.ts's own same-turn DENY (repeated same-tool failures within ~9-10 calls, an
      // independently-tuned fixed-count threshold, not scaled to maxSteps) must get a genuine
      // chance to fire first — a fractional split (half of maxSteps=15 -> 8) sat BELOW that
      // threshold and silently preempted it before it ever ran. A fixed, small reservation
      // stays out of that mechanism's way for any maxSteps large enough for it to matter, at
      // the cost of a genuinely small maxSteps (e.g. 6) leaving little room for either.
      maxIterations: Math.max(3, this.maxSteps - RECOVERY_HEADROOM),
      sources, onToken, onToolStep, onUsage, riskHint, takeSteeringNotes, stepInstruction, shareAnswer,
    })
    return { proposer, sources }
  }

  /**
   * R4 of the internal plan: the batch-research counterpart to
   * `createOneLoopProposer` above — routes `runBatchToolLoop`'s probe → calibrate → confirm-gate
   * → resolve-remaining → synthesize sequence through the same harness-driven proposer mechanism,
   * instead of batch research remaining a second code path that (per R3) never reached the
   * harness regardless of the flag. Reuses `resolveBatchItem`/`resolveRemainingBatchItems`/
   * `synthesizeBatchReply` verbatim — the exact same methods the flag-OFF path calls — so the
   * dead-end window (local `toolYields`, scoped inside `resolveBatchItem`) and the calibrated
   * per-item budget (`resolveRemainingBatchItems`'s own `Budget`/`nextItemBudget` logic) keep
   * bounding a hard item's spend identically; nothing here reimplements that math.
   *
   * The closure advances through three phases, one per `driveMainLoop` iteration (i.e. one
   * `__harnessExecutionStatus: 'continue'` per phase transition) rather than one per underlying
   * tool call the way the flat proposer does: 'probe' (resolve every probe item, calibrate, and
   * either throw a `needs_approval` OneLoopPause — mirroring `runBatchToolLoop`'s own confirmation
   * gate, including persisting the same `BatchPendingState` so the existing, flag-independent
   * `resolvePendingBatchConfirmation` resume path needs no changes — or fall through), 'resolve'
   * (resolve every remaining item in one `resolveRemainingBatchItems` call), and 'synthesize'
   * (stream the final reply via `synthesizeBatchReply`, preserving its existing token-by-token
   * `onToken` semantics, then return `'complete'`). This is coarser-grained resumability than the
   * flat proposer's per-tool-call steps — a deliberate scope decision (see this phase's
   * implementation note) rather than reimplementing `resolveRemainingBatchItems`'s calibration
   * loop one item at a time just to get finer-grained checkpoints.
   */
  createBatchOneLoopProposer(
    items: string[],
    sessionId: string,
    userMessage: string,
    systemPrompt: string,
    onToken?: (token: string) => void,
    onToolStep?: (step: AssistantToolStep) => void,
    onUsage?: (usage: TokenUsage) => void,
  ): {
    proposer: (toolCtx: ToolExecutorContext) => Promise<unknown>
    sources: AssistantSource[]
    getBatchBudget: () => BatchBudgetTrace | undefined
  } {
    const probeCount = items.length === 3 ? 1 : 2
    const probeItems = items.slice(0, probeCount)
    const remainingItems = items.slice(probeCount)

    const sources: AssistantSource[] = []
    let phase: 'probe' | 'resolve' | 'synthesize' | 'done' = 'probe'
    const probeResolutions: BatchItemResolution[] = []
    let allResolutions: BatchItemResolution[] = []
    let notAttempted: string[] = []
    let projectedTotal = 0
    let batchBudget: BatchBudgetTrace | undefined
    // One real, turn-scoped live ControlState shared across every batch item — the same object the
    // flag-OFF runBatchToolLoop path threads through resolveBatchItem / resolveRemainingBatchItems
    // (createControlPlaneState). It must be a real createControlPlaneState() object, not a
    // synthetic { controlState } wrapper: resolveBatchItem's shared runToolIterationStep calls
    // recordToolOutcome unconditionally when a controlPlaneState is passed, and recordToolOutcome
    // dereferences state.evidenceStore. Batch items don't pin toolCtx.controlState in the way the
    // flat proposer does — they already cleared the message-level approval gate, and the flag-OFF
    // batch path gates on this turn-scoped state alone too.
    const controlPlaneState = this.createControlPlaneState()

    const proposer = async (_toolCtx: ToolExecutorContext): Promise<unknown> => {
      if (phase === 'probe') {
        for (const item of probeItems) {
          probeResolutions.push(
            await this.resolveBatchItem(item, BATCH_PROBE_ITEM_CAP, items, systemPrompt, sessionId, onToolStep, onUsage, controlPlaneState),
          )
        }

        const callsPerItemHistory = probeResolutions.map((r) => r.callsUsed)
        const callsPerItem = Math.max(BATCH_PER_ITEM_FLOOR, trimmedAverage(callsPerItemHistory))
        projectedTotal = callsPerItem * remainingItems.length * BATCH_SLACK_FACTOR

        if (remainingItems.length > 0 && projectedTotal > BATCH_LARGE_PROJECTION_THRESHOLD) {
          const pendingActionId = crypto.randomUUID()
          const pendingState: BatchPendingState = {
            userMessage,
            systemPrompt,
            sessionId,
            probedResults: probeResolutions,
            remainingItems,
            projectedTotal,
          }
          await this.memory.set(`batch-pending:${pendingActionId}`, pendingState)
          phase = 'done'
          throw new OneLoopPause({
            kind: 'needs_approval',
            reason:
              `This looks like it'll take ~${Math.ceil(projectedTotal)} more searches to cover the remaining ` +
              `${remainingItems.length} item(s) — continue, or should I do a quick pass first?`,
            pendingActionId,
            pendingActionKind: 'batch',
          })
        }

        phase = 'resolve'
        return { __harnessExecutionStatus: 'continue' }
      }

      if (phase === 'resolve') {
        const resolved = await this.resolveRemainingBatchItems(
          probeResolutions, remainingItems, systemPrompt, sessionId, onToolStep, onUsage, controlPlaneState,
        )
        allResolutions = resolved.resolutions
        notAttempted = resolved.notAttempted
        sources.push(...allResolutions.flatMap((r) => r.sources))
        phase = 'synthesize'
        return { __harnessExecutionStatus: 'continue' }
      }

      if (phase === 'synthesize') {
        const content = await this.synthesizeBatchReply(userMessage, systemPrompt, allResolutions, notAttempted, onToken, onUsage)
        batchBudget = buildBatchBudgetTrace(items.length, projectedTotal, allResolutions)
        phase = 'done'
        return { __harnessExecutionStatus: 'complete', output: content }
      }

      throw new Error('Batch one-loop proposer invoked after completion')
    }

    return { proposer, sources, getBatchBudget: () => batchBudget }
  }

  /**
   * Phase 4/4c: the deterministic, harness-state-informed authority for whether `toolName` may
   * proceed — see tool-policy.ts. `controlState` is the live, per-turn ControlState built by
   * tool-control-plane.ts and threaded down from runTurn (see createTurnControlPlaneState);
   * `undefined` at the very first tool call of a turn (nothing recorded yet — the pre-evidence
   * baseline tool-policy.ts's own doc comment describes) or for a caller that never wired one in.
   */
  private checkToolPolicy(
    toolName: string,
    riskHint: TurnIntentClassification['riskLevel'],
    controlState?: TurnControlPlaneState['controlState'],
  ): ReturnType<typeof evaluateToolPolicy> {
    const result = evaluateToolPolicy({ toolName, riskHint, controlState })
    this.onTrace?.({ kind: 'tool_policy_decision', tool: toolName, decision: result.decision, reason: result.reason })
    return result
  }

  /**
   * Bounded ReAct loop: calls callChatStructured with whichever of file/web/shell/reminder
   * tools are configured, executing real (non-mutating) tool calls and looping, until
   * either a final text reply comes back, a write_file/run_shell_command call needs
   * staging + approval, or the iteration cap is hit. Only ever invoked when `fileTools`,
   * `webTools`, or `shellTools` is configured (reminder tools ride along whenever any of
   * those does, since `reminderStore` always exists).
   */
  async runToolLoop(
    sessionId: string,
    transcript: ChatMessage[],
    userMessage: string,
    systemPrompt: string,
    onToken?: (token: string) => void,
    onToolStep?: (step: AssistantToolStep) => void,
    onUsage?: (usage: TokenUsage) => void,
    riskHint: TurnIntentClassification['riskLevel'] = 'LOW',
    controlPlaneState?: TurnControlPlaneState,
  ): Promise<ToolLoopResult> {
    const tools = [
      ...(this.fileTools ? FILE_TOOLS : []),
      ...(this.webTools ? WEB_TOOLS : []),
      ...(this.shellTools ? SHELL_TOOLS : []),
      ...(this.actionTools ? ACTION_TOOLS : []),
      ...REMINDER_TOOLS,
      ...this.recallTools(),
    ]
    const messages: ChatMessage[] = [
      { role: 'system', content: systemPrompt },
      ...transcript,
      { role: 'user', content: userMessage },
    ]
    const { result } = await this.runToolIterations(messages, this.maxSteps, tools, sessionId, userMessage, onToken, onToolStep, onUsage, undefined, riskHint, controlPlaneState)
    return result
  }

  /**
   * The actual ReAct-style tool-calling loop, factored out of runToolLoop so a batch sub-loop
   * (resolveBatchItem, below) can run the exact same iteration logic — including the
   * looksLikeUnparsedToolCall retry guard and write/shell staging — scoped to its own message
   * history and its own (usually much smaller) iteration budget, instead of duplicating it.
   * `maxIterations` replaces runToolLoop's former direct use of `this.maxSteps`; passing
   * `this.maxSteps` here reproduces that method's exact prior behavior unchanged.
   *
   * `onToolResult`, when provided, is called after every tool result is folded into `messages`
   * and may return `'stop'` to end the loop immediately (see resolveBatchItem's item-scoped
   * dead-end window) — a caller that never passes it (runToolLoop, the flat non-batch path)
   * gets today's unmodified behavior: the loop only ever ends via a final answer, an
   * needs_approval bail-out, or maxIterations.
   *
   * Thin wrapper (R1 of the D2 one-loop-rewire follow-up plan) around
   * `runToolIterationStep`, which does one iteration's worth of work and returns a discriminated
   * `done`/`not done` result — the shape a harness-driven `driveMainLoop` can call once per its
   * own iteration (R2), instead of only ever being driven by this method's own `for` loop.
   */
  private async runToolIterations(
    messages: ChatMessage[],
    maxIterations: number,
    tools: ToolDefinition[],
    sessionId: string,
    userMessage: string,
    onToken?: (token: string) => void,
    onToolStep?: (step: AssistantToolStep) => void,
    onUsage?: (usage: TokenUsage) => void,
    onToolResult?: (toolName: string, resultText: string) => 'continue' | 'stop',
    riskHint: TurnIntentClassification['riskLevel'] = 'LOW',
    controlPlaneState?: TurnControlPlaneState,
  ): Promise<{ result: ToolLoopResult; iterationsUsed: number; deadEndStopped?: boolean }> {
    const sources: AssistantSource[] = []
    let dispatchedAnyToolCall = false

    for (let iteration = 0; iteration < maxIterations; iteration++) {
      const step = await this.runToolIterationStep(
        messages, tools, sessionId, userMessage, sources, dispatchedAnyToolCall,
        onToken, onToolStep, onUsage, onToolResult, riskHint, controlPlaneState,
      )
      if (step.done) {
        return { result: step.result, iterationsUsed: iteration + 1, deadEndStopped: step.deadEndStopped }
      }
      dispatchedAnyToolCall = step.dispatchedAnyToolCall
    }

    return {
      result: { kind: 'escalated', reason: `Tool loop exceeded ${maxIterations} iterations without producing a final answer.` },
      iterationsUsed: maxIterations,
    }
  }

  /**
   * One iteration's worth of `runToolIterations`' ReAct loop, extracted (R1 of the D2
   * one-loop-rewire follow-up plan, the internal plan) so a
   * harness-driven proposer (R2) can call this directly, once per `driveMainLoop` iteration,
   * instead of only ever being driven by `runToolIterations`' own `for` loop. Preserves every
   * early-return branch of the original loop body exactly — the unparsed-tool-call retry,
   * `__staged_action` adoption, write/shell/email staging, cached-shell replay, per-call
   * `tool-policy.ts` DENY/REQUIRE_APPROVAL, and the `onToolResult` dead-end-window stop — as a
   * `{ done: true, result }` return; the two cases that used to `continue` the outer `for` loop
   * (the unparsed-tool-call retry and a cached-shell replay) become `{ done: false, ... }`
   * instead, with `dispatchedAnyToolCall` threaded back to the caller since it must persist
   * across iterations. `sources` is mutated in place (pushed to) rather than threaded through
   * the result, since it's a plain accumulator shared by reference across every step call for
   * the same loop.
   */
  private async runToolIterationStep(
    messages: ChatMessage[],
    tools: ToolDefinition[],
    sessionId: string,
    userMessage: string,
    sources: AssistantSource[],
    dispatchedAnyToolCall: boolean,
    onToken?: (token: string) => void,
    onToolStep?: (step: AssistantToolStep) => void,
    onUsage?: (usage: TokenUsage) => void,
    onToolResult?: (toolName: string, resultText: string) => 'continue' | 'stop',
    // Phase 4: advisory input to ToolPolicy (tool-policy.ts) — never itself the gate. Defaults to
    // 'LOW' for callers that don't have a per-turn classification in scope (resolveBatchItem's
    // batch sub-loop below), which is conservative-neutral: it only affects ToolPolicy's
    // fail-safe 'UNKNOWN' branch, and a batch item's own turn already passed the message-level
    // requiresApproval gate before ever reaching here.
    riskHint: TurnIntentClassification['riskLevel'] = 'LOW',
    // Phase 4c: shared, turn-scoped live ControlState (tool-control-plane.ts), constructed once
    // by runTurn and threaded through every sub-loop that dispatches tool calls within the same
    // turn — including across batch items, so a failure pattern discovered in one item's sub-loop
    // is visible to the next item's, not reset per call. `undefined` for callers that never wire
    // one in (e.g. resolvePendingBatchConfirmation's resume path — see tool-control-plane.ts's own
    // doc comment on why that's a deliberate scope boundary, not an oversight).
    controlPlaneState?: TurnControlPlaneState,
  ): Promise<
    | { done: true; result: ToolLoopResult; deadEndStopped?: boolean }
    | { done: false; dispatchedAnyToolCall: boolean }
  > {
    // Reports a step immediately, before the call executes — a caller wants to see "reading
    // notes.txt" while it's happening, not just after the fact.
    const reportStep = (tool: string, input: Record<string, unknown>): void => {
      onToolStep?.({ tool, input, summary: summarizeToolStep(tool, input) })
    }
    // A second, follow-up report fired only when tool-policy denies a call reportStep already
    // announced — see AssistantToolStep.deniedReason's doc comment. Without this, a denied
    // read-only call was invisible to the user: the model saw the denial in its own conversation,
    // but nothing was ever printed to say the call didn't happen.
    const reportDenied = (tool: string, input: Record<string, unknown>, reason: string): void => {
      onToolStep?.({ tool, input, summary: summarizeToolStep(tool, input), deniedReason: reason })
    }

    {
      // For the claude-cli backend, this one call may run several tool round trips
      // internally (Claude Code's own agentic loop) before returning — onToolStep here is
      // what makes those otherwise-invisible calls show up live; for the proxy backend,
      // this backend option is simply never invoked (one call = one round trip, already
      // visible below), so reportStep covers it there instead.
      const response = await this.llmClient.callChatStructured(messages, tools, {
        model: this.model(),
        onToolStep: onToolStep ? (event) => reportStep(event.tool, event.input) : undefined,
        onUsage,
        // Phase D0: for a backend that can intercept its own internal tool loop before a
        // read-only call executes (currently ClaudeCliLLMClient — see its own doc comment),
        // this is the propose→gate half of propose→gate→execute: the exact same deterministic
        // checkToolPolicy gate the manual dispatch loop below already runs for every call it
        // makes directly, now also covering the calls this backend used to resolve invisibly.
        // A backend without such an internal loop (the proxy client) never calls this — its
        // calls come back as response.toolCalls and are gated inline below instead.
        onToolProposal: async (tool, input) => {
          const policy = this.checkToolPolicy(tool, riskHint, controlPlaneState?.controlState)
          if (policy.decision === 'ALLOW') return { decision: 'allow' }
          reportDenied(tool, input, policy.reason)
          return { decision: 'deny', reason: policy.reason }
        },
        // The report half: a backend that runs its own tool loop (claude-cli) hands back what each
        // read-only call returned, so this turn's sources carry the raw text the grounding check
        // compares the reply to — the manual dispatch loop below does the same for the calls it
        // makes itself. Same tools and same `path` meaning as that loop's own source push.
        // Run fetch_url / web_search on this side when web tools are configured, so a claude-cli
        // fetch gets the same SSRF guard, injected fetch and LLM injection check the manual dispatch
        // loop gives the proxy backend (executeToolCall). Declines (undefined) without webTools —
        // the MCP server then fetches for itself, as before.
        onToolExecute: async (tool, input) => {
          if (tool === 'recall_memory') {
            // Served on this side: the MCP subprocess has no digest store. Already passed the gate above.
            return this.digestReader && recallToolEnabled() ? this.executeToolCall(tool, input, userMessage, onUsage) : undefined
          }
          if (!this.webTools || (tool !== 'fetch_url' && tool !== 'web_search')) return undefined
          const text = await this.executeToolCall(tool, input, userMessage, onUsage)
          sources.push({ tool, path: String(input.query ?? input.url), excerpt: text.slice(0, GROUNDING_EXCERPT_CHARS) })
          return text
        },
        onToolResult: (tool, input, resultText, ok, notFound) => {
          // Fold this call's outcome into the turn's ControlState, exactly as the manual dispatch loop does for the calls
          // it makes itself — before this, a claude-cli turn's failures never reached the state checkToolPolicy reads,
          // so the gate evaluated every call against a state that could not change (14 ALLOWs after 13 failed reads).
          if (controlPlaneState) {
            recordToolOutcome(controlPlaneState, {
              toolName: tool,
              // a missing file is the tool working and answering "no" — see ToolOutcome.negative
              ok: ok || notFound === true,
              negative: notFound === true,
              callKey: `${tool}:${JSON.stringify(input)}`,
              summary: notFound ? `${tool} found nothing: ${resultText.slice(0, 200)}` : ok ? `${tool} succeeded` : `${tool} failed: ${resultText.slice(0, 200)}`,
            })
          }
          if (tool === 'read_file' || tool === 'list_directory') {
            sources.push({ tool, path: String(input.path), excerpt: resultText.slice(0, GROUNDING_EXCERPT_CHARS) })
          } else if (tool === 'web_search' || tool === 'fetch_url') {
            sources.push({ tool, path: String(input.query ?? input.url), excerpt: resultText.slice(0, GROUNDING_EXCERPT_CHARS) })
          }
        },
      })

      if (!response.toolCalls || response.toolCalls.length === 0) {
        if (looksLikeUnparsedToolCall(response.content)) {
          // Never show this to the user as if it were a real answer — nudge the model to
          // either call a tool properly or answer in plain text, and retry. Bounded by the
          // same maxIterations cap as any other iteration (enforced by the wrapper's loop): a
          // model that keeps doing this falls through to the 'escalated' return below instead
          // of ever reaching the user.
          messages.push({ role: 'assistant', content: response.content })
          messages.push({
            role: 'user',
            content: 'Your last reply contained unparsed tool-call syntax (a literal "<tool_call>" tag) instead of either a real tool call or a plain-text answer. Do not include any tool-call-like tags in your reply — either call a tool, or answer in plain text.',
          })
          return { done: false, dispatchedAnyToolCall }
        }

        if (!onToken) return { done: true, result: { kind: 'final', content: response.content, sources } }

        if (!dispatchedAnyToolCall) {
          // No tool result was ever manually folded into `messages` this turn — true for
          // the claude-cli backend, whose own agentic loop resolves every tool call
          // invisibly inside the one callChatStructured call already made above. Re-asking
          // via callChat here would replay the *original* question with none of that
          // context (and, for ClaudeCliLLMClient specifically, --mcp-config stripped back
          // to zero tools — see EMPTY_MCP_CONFIG), so it isn't "the same answer, streamed"
          // at all — it's the model's ungrounded blind guess, silently overwriting a
          // correct, tool-grounded reply with a wrong one. Just deliver the already-correct
          // content through onToken directly; no second call, no risk of losing grounding.
          onToken(response.content)
          return { done: true, result: { kind: 'final', content: response.content, sources } }
        }

        // Re-request the same final answer as a real streamed completion — only
        // reached once this loop has actually dispatched a tool call itself (the proxy
        // backend's shape), where `messages` already carries the enriched tool-result
        // history, so re-asking here gets an equally-grounded answer, just delivered
        // token-by-token instead of all at once.
        let streamed = ''
        for await (const token of this.llmClient.callChat(messages, { model: this.model(), onUsage })) {
          streamed += token
          onToken(token)
        }
        return { done: true, result: { kind: 'final', content: streamed, sources } }
      }

      // The Claude CLI backend's own agentic loop resolves read/list/web calls internally
      // within one subprocess call, and — because write_file/run_shell_command must never
      // execute inline for that backend either — its MCP tool handler already staged the
      // action itself before returning here. It signals that with this synthetic tool name
      // instead of write_file/run_shell_command, so we adopt the id it already staged rather
      // than staging a second, redundant pending action.
      const alreadyStagedCall = response.toolCalls.find(call => call.name === '__staged_action')
      if (alreadyStagedCall) {
        const { id, kind, ...payload } = alreadyStagedCall.input as { id: string; kind: 'write' | 'shell' | 'email' } & Record<string, unknown>
        if (kind === 'write') {
          const { path, content } = payload as { path: string; content: string }
          const previousContent = this.fileTools
            ? await readCurrentFileContent(this.fileTools.backend, this.fileTools.workspaceRoot, path)
            : undefined
          return {
            done: true,
            result: {
              kind: 'needs_approval',
              reason: `Proposes writing to "${path}":\n${formatWriteDiff(previousContent, content)}`,
              pendingActionId: id,
              pendingActionKind: 'write',
            },
          }
        }
        if (kind === 'email') {
          const { to, subject, body } = payload as { to: string; subject: string; body: string }
          return {
            done: true,
            result: {
              kind: 'needs_approval',
              reason: formatEmailApprovalReason({ to, subject, body }),
              pendingActionId: id,
              pendingActionKind: 'email',
            },
          }
        }
        const { command, cwd } = payload as { command: string; cwd: string }
        return {
          done: true,
          result: {
            kind: 'needs_approval',
            reason: shellApprovalReason(command, cwd),
            pendingActionId: id,
            pendingActionKind: 'shell',
          },
        }
      }

      const writeCall = response.toolCalls.find(call => call.name === 'write_file')
      if (writeCall) {
        if (!this.fileTools) throw new Error('write_file tool call received but fileTools is not configured')
        reportStep('write_file', writeCall.input)
        // Stop immediately — don't execute any other tool calls from this same
        // response — and stage the write rather than ever touching real disk.
        const result = await executeFileTool(this.fileTools, 'write_file', writeCall.input)
        if (result.kind !== 'staged_write') {
          throw new Error('write_file executor returned an unexpected result kind')
        }
        const previousContent = await readCurrentFileContent(this.fileTools.backend, this.fileTools.workspaceRoot, result.path)
        return {
          done: true,
          result: {
            kind: 'needs_approval',
            reason: `Proposes writing to "${result.path}":\n${formatWriteDiff(previousContent, result.content)}`,
            pendingActionId: result.id,
            pendingActionKind: 'write',
          },
        }
      }

      const shellCall = response.toolCalls.find(call => call.name === 'run_shell_command')
      if (shellCall) {
        if (!this.shellTools) throw new Error('run_shell_command tool call received but shellTools is not configured')
        reportStep('run_shell_command', shellCall.input)
        // Every run_shell_command call is gated, full stop — there is no "safe subset" that
        // skips staging, including an identical repeat of an already-resolved (command, cwd) pair
        // (its result may no longer reflect current state).
        const result = await executeShellTool(this.shellTools, 'run_shell_command', shellCall.input)
        return {
          done: true,
          result: {
            kind: 'needs_approval',
            reason: shellApprovalReason(result.command, result.cwd),
            pendingActionId: result.id,
            pendingActionKind: 'shell',
          },
        }
      }

      const emailCall = response.toolCalls.find(call => call.name === 'send_email')
      if (emailCall) {
        if (!this.actionTools) throw new Error('send_email tool call received but actionTools is not configured')
        reportStep('send_email', emailCall.input)
        // Same as write_file/run_shell_command: stop immediately, stage the proposal, never deliver
        // inline. executeActionTool throws InvalidEmailArgsError on a malformed recipient — that
        // propagates and the loop's own error handling turns it into a tool error the model sees.
        const result = await executeActionTool(this.actionTools, 'send_email', emailCall.input)
        return {
          done: true,
          result: {
            kind: 'needs_approval',
            reason: formatEmailApprovalReason(result),
            pendingActionId: result.id,
            pendingActionKind: 'email',
          },
        }
      }

      messages.push({ role: 'assistant', content: response.content, toolCalls: response.toolCalls })
      for (const call of response.toolCalls) {
        reportStep(call.name, call.input)
        // Phase 4/4c: deterministic, harness-state-informed gate, checked before this call
        // executes rather than only classified in advance and never re-checked — see
        // tool-policy.ts. controlPlaneState?.controlState is the live ControlState built from
        // every earlier tool call this turn (see recordToolOutcome below) — undefined only for
        // this turn's very first tool call, or a caller that never wired one in.
        const policy = this.checkToolPolicy(call.name, riskHint, controlPlaneState?.controlState)
        if (policy.decision === 'DENY') {
          const resultText = `Denied by tool policy: ${policy.reason}`
          reportDenied(call.name, call.input, policy.reason)
          messages.push({ role: 'tool', content: resultText, toolCallId: call.id })
          this.onTrace?.({ kind: 'tool_call', tool: call.name, ok: false })
          continue
        }
        if (policy.decision === 'REQUIRE_APPROVAL') {
          // Unlike write_file/run_shell_command (which stage a concrete, resumable action by ID
          // — see file-tools.ts's stagePendingAction), a read-only tool call ToolPolicy flags here
          // has nothing concrete to stage: the harness's own control state, not a specific
          // pending mutation, is what's asking for a human to look at this turn before more tool
          // use continues. Surfaced as an escalation (same shape maxIterations exhaustion already
          // uses below) rather than a fabricated needs_approval with no real pendingActionId
          // behind it.
          return {
            done: true,
            result: { kind: 'escalated', reason: policy.reason },
          }
        }
        let resultText: string
        let toolOk = true
        let toolNegative = false
        try {
          resultText = await this.executeToolCall(call.name, call.input, userMessage, onUsage)
          this.onTrace?.({ kind: 'tool_call', tool: call.name, ok: true })
          this.onDebugLog?.({
            kind: 'tool_call',
            sessionId,
            content: `${call.name}(${JSON.stringify(call.input)}) →\n${resultText.slice(0, 4000)}${resultText.length > 4000 ? `\n… (truncated, ${resultText.length} chars total)` : ''}`,
          })
          // Only a call that actually succeeded grounds the reply in something
          // real — a rejected path/URL or tool error below is reported to the
          // model but isn't a source.
          if (call.name === 'read_file' || call.name === 'list_directory') {
            sources.push({ tool: call.name, path: String(call.input.path), excerpt: resultText.slice(0, GROUNDING_EXCERPT_CHARS) })
          } else if (call.name === 'web_search' || call.name === 'fetch_url') {
            sources.push({ tool: call.name, path: String(call.input.query ?? call.input.url), excerpt: resultText.slice(0, GROUNDING_EXCERPT_CHARS) })
          }
        } catch (err) {
          // A rejected path or tool error is reported back to the model as a
          // tool result, not thrown — matches the "clear decline, never a
          // silent no-op dressed up as success" baseline this plan preserves.
          // Also logged here (not just fed to the model) — this catch otherwise leaves the
          // real cause invisible everywhere: it never reaches App.tsx's own catch (no
          // exception propagates past this point), and the model's own paraphrase of the
          // error in its final reply is rarely the actual message.
          console.error(`[tool call failed] ${call.name}`, err)
          this.onTrace?.({ kind: 'tool_call', tool: call.name, ok: false })
          resultText = `Error: ${err instanceof Error ? err.message : String(err)}`
          this.onDebugLog?.({ kind: 'tool_call', sessionId, content: `${call.name}(${JSON.stringify(call.input)}) → ${resultText}` })
          // A missing file is the tool working and answering "no such file", not a fault (ToolOutcome.negative).
          toolNegative = err instanceof ToolNotFoundError
          toolOk = toolNegative
        }
        // Phase 4c: feed this call's outcome into the same live ControlState checkToolPolicy
        // reads at the top of the next iteration of this loop — a short summary only, never the
        // full resultText (which can be large or come from untrusted web content).
        if (controlPlaneState) {
          recordToolOutcome(controlPlaneState, {
            toolName: call.name,
            ok: toolOk,
            negative: toolNegative,
            callKey: `${call.name}:${JSON.stringify(call.input)}`,
            summary: toolNegative ? `${call.name} found nothing: ${resultText.slice(0, 200)}` : toolOk ? `${call.name} succeeded` : `${call.name} failed: ${resultText.slice(0, 200)}`,
          })
        }
        messages.push({ role: 'tool', content: resultText, toolCallId: call.id })

        if (onToolResult && onToolResult(call.name, resultText) === 'stop') {
          return { done: true, result: { kind: 'final', content: response.content, sources }, deadEndStopped: true }
        }
      }
    }

    return { done: false, dispatchedAnyToolCall: true }
  }

  /**
   * Resolves one batch item in its own bounded sub-loop — structurally the same
   * runToolIterations call the flat loop uses, just seeded with a single-item-focused user
   * message and a per-item budget instead of the whole conversation and `this.maxSteps`.
   *
   * The dead-end window (`toolYields`) is a local array, created fresh on every call to this
   * method — never shared across items: a hard item that trips BATCH_DEAD_END_WINDOW
   * consecutive dead_end results only stops *this* item's sub-loop early (rather than spending
   * the rest of its budget on a dead page) and can never poison an easier item queued behind it.
   */
  private async resolveBatchItem(
    item: string,
    budget: number,
    batchItems: string[],
    systemPrompt: string,
    sessionId: string,
    onToolStep?: (step: AssistantToolStep) => void,
    onUsage?: (usage: TokenUsage) => void,
    controlPlaneState?: TurnControlPlaneState,
  ): Promise<BatchItemResolution> {
    const tools = [
      ...(this.fileTools ? FILE_TOOLS : []),
      ...(this.webTools ? WEB_TOOLS : []),
      ...(this.shellTools ? SHELL_TOOLS : []),
      ...(this.actionTools ? ACTION_TOOLS : []),
      ...REMINDER_TOOLS,
      ...this.recallTools(),
    ]
    const itemPrompt =
      `You are working through one item from a batch research request covering ${batchItems.length} similar ` +
      `items in total. Find the requested information for just this one item, using the available tools as ` +
      `needed:\n\n"${item}"\n\nAnswer only for this item — a separate pass handles the others. Be concise and ` +
      'ground your answer in what the tools actually returned; say plainly if nothing could be found.'
    const messages: ChatMessage[] = [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: itemPrompt },
    ]

    const toolYields: ToolYield[] = []
    const trackYield = (toolName: string, resultText: string): 'continue' | 'stop' => {
      if (toolName !== 'web_search' && toolName !== 'fetch_url') return 'continue'
      toolYields.push(classifyToolYield(toolName, resultText))
      const trailing = toolYields.slice(-BATCH_DEAD_END_WINDOW)
      return trailing.length === BATCH_DEAD_END_WINDOW && trailing.every((y) => y === 'dead_end') ? 'stop' : 'continue'
    }

    const { result, iterationsUsed, deadEndStopped } = await this.runToolIterations(
      messages, budget, tools, sessionId, itemPrompt, undefined, onToolStep, onUsage, trackYield, undefined, controlPlaneState,
    )

    if (deadEndStopped) {
      const sources = result.kind === 'final' ? result.sources : []
      return {
        item,
        content:
          `No results found for "${item}" after ${BATCH_DEAD_END_WINDOW} consecutive unproductive searches — ` +
          'treating as not found rather than continuing to spend this item\'s budget.',
        callsUsed: iterationsUsed,
        exhausted: false,
        status: 'not_found',
        sources,
      }
    }
    if (result.kind === 'final') {
      return { item, content: result.content, callsUsed: iterationsUsed, exhausted: false, status: 'found', sources: result.sources }
    }
    if (result.kind === 'escalated') {
      // maxIterations was reached without a final answer, but the dead-end window above never
      // tripped — this item was still turning up plausibly-relevant content when its budget ran
      // out, not stuck on a dead page.
      return { item, content: `(Could not resolve within budget: ${result.reason})`, callsUsed: iterationsUsed, exhausted: true, status: 'truncated_while_productive', sources: [] }
    }
    // 'needs_approval': a write_file/run_shell_command call inside a batch item is out of scope
    // for a batch-research turn (there is no per-item place to route an approval prompt) — surfaced
    // as an unresolved item rather than silently dropping the request or applying it unreviewed.
    return { item, content: `(Could not resolve — this item's tool call needs approval: ${result.reason})`, callsUsed: iterationsUsed, exhausted: true, status: 'not_found', sources: [] }
  }

  /**
   * Resolves every item in `remainingItems` in its own sub-loop, recalibrating the per-item
   * budget after each one via nextItemBudget instead of freezing it at the initial probe
   * average, and stopping once the running total hits BATCH_ABSOLUTE_TURN_CEILING regardless of
   * how favorable calibration still looks. Returns every resolution so far (probed + newly
   * resolved) plus the names of any items never attempted because the ceiling was hit first.
   * Public — also called by ActionApprovalService.resolvePendingBatchConfirmation on the
   * approved-continuation path.
   */
  async resolveRemainingBatchItems(
    probedResults: BatchItemResolution[],
    remainingItems: string[],
    systemPrompt: string,
    sessionId: string,
    onToolStep?: (step: AssistantToolStep) => void,
    onUsage?: (usage: TokenUsage) => void,
    controlPlaneState?: TurnControlPlaneState,
  ): Promise<{ resolutions: BatchItemResolution[]; notAttempted: string[] }> {
    const resolutions: BatchItemResolution[] = [...probedResults]
    const budgetState: BatchBudgetState = {
      callsPerItemHistory: probedResults.map((r) => r.callsUsed),
      perItemFloor: BATCH_PER_ITEM_FLOOR,
      slackFactor: BATCH_SLACK_FACTOR,
      absoluteTurnCeiling: BATCH_ABSOLUTE_TURN_CEILING,
    }
    // Aggregate turn-wide ceiling, tracked via the generic Budget type (packages/harness) rather
    // than a bare counter compared against the module constant — same isExhausted()/consume()
    // shape as adapter/harness/recovery.py's RecoveryBudget. Only the `calls` dimension is used
    // here; cost/time/parallelism stay at their default-unbounded value since batch-research
    // doesn't track those today.
    let turnBudget = new Budget({ maxCalls: BATCH_ABSOLUTE_TURN_CEILING }).consume({
      calls: budgetState.callsPerItemHistory.reduce((sum, c) => sum + c, 0),
    })
    const allItems = [...probedResults.map((r) => r.item), ...remainingItems]

    for (const item of remainingItems) {
      if (turnBudget.isExhausted()) break
      const budget = Math.max(1, Math.min(nextItemBudget(budgetState), turnBudget.remaining('calls')))
      const resolution = await this.resolveBatchItem(item, budget, allItems, systemPrompt, sessionId, onToolStep, onUsage, controlPlaneState)
      resolutions.push(resolution)
      budgetState.callsPerItemHistory.push(resolution.callsUsed)
      turnBudget = turnBudget.consume({ calls: resolution.callsUsed })
    }

    const notAttempted = remainingItems.slice(resolutions.length - probedResults.length)
    return { resolutions, notAttempted }
  }

  /**
   * Synthesizes one final reply from every item's per-item findings — same shape as the flat
   * loop's own final-answer call, just seeded with structured per-item results instead of raw
   * tool-call history for every item at once.
   *
   * Any item in `notAttempted` (the absolute ceiling was hit before it was ever reached) is
   * appended as a deterministic, guaranteed-present list rather than left to the synthesis
   * call's prose — an LLM asked to "write one well-organized reply" over many items can drop one
   * from its summary the same way it can drop one from a longer todo list; the per-item
   * `resolutions` themselves stay inside the model's synthesis (their found/not_found/
   * truncated_while_productive wording is already baked into `content` by resolveBatchItem, so
   * the model has no need to invent that part), but which items were never even attempted this
   * turn is a plain fact, not something worth trusting to how well the model followed
   * instructions. Public — also called by ActionApprovalService.
   */
  async synthesizeBatchReply(
    userMessage: string,
    systemPrompt: string,
    resolutions: BatchItemResolution[],
    notAttempted: string[],
    onToken?: (token: string) => void,
    onUsage?: (usage: TokenUsage) => void,
  ): Promise<string> {
    const findingsBlock = resolutions.map((r) => `### ${r.item}\n${r.content}`).join('\n\n')
    const notAttemptedNote =
      notAttempted.length > 0
        ? `\n\nThe following items were not attempted this turn (ran out of room) and are appended to the reply ` +
          `separately — do not mention them yourself: ${notAttempted.join(', ')}`
        : ''
    const synthesisPrompt =
      `The user's original batch research request: "${userMessage}"\n\n` +
      `Per-item findings gathered so far:\n${findingsBlock}${notAttemptedNote}\n\n` +
      "Write one well-organized reply covering every item above. For any item whose findings couldn't be " +
      'resolved, say so plainly — never invent or guess a value.'

    let finalContent = ''
    for await (const token of this.llmClient.callChat(
      [{ role: 'system', content: systemPrompt }, { role: 'user', content: synthesisPrompt }],
      { model: this.model(), onUsage },
    )) {
      finalContent += token
      onToken?.(token)
    }

    if (notAttempted.length === 0) return finalContent
    const guaranteedNotAttempted = `\n\nNot yet checked this turn (ran out of room): ${notAttempted.join(', ')}`
    onToken?.(guaranteedNotAttempted)
    return finalContent + guaranteedNotAttempted
  }

  /**
   * Gated entry point for the batch-research path: probes the first 1-2 items (keeping at least
   * one item unprobed so a single sample can't swing the whole projection), calibrates a
   * per-item budget off their real cost, and either pauses for confirmation (a large projection)
   * or resolves every remaining item and synthesizes the final reply.
   */
  async runBatchToolLoop(
    items: string[],
    sessionId: string,
    userMessage: string,
    systemPrompt: string,
    onToken?: (token: string) => void,
    onToolStep?: (step: AssistantToolStep) => void,
    onUsage?: (usage: TokenUsage) => void,
    controlPlaneState?: TurnControlPlaneState,
  ): Promise<ToolLoopResult> {
    // Probe phase: N==3 probes just item[0] so at least one item stays unprobed even for the
    // smallest qualifying batch; larger batches probe the first two.
    const probeCount = items.length === 3 ? 1 : 2
    const probeItems = items.slice(0, probeCount)
    const remainingItems = items.slice(probeCount)

    const probeResolutions: BatchItemResolution[] = []
    for (const item of probeItems) {
      probeResolutions.push(await this.resolveBatchItem(item, BATCH_PROBE_ITEM_CAP, items, systemPrompt, sessionId, onToolStep, onUsage, controlPlaneState))
    }

    // Calibrate.
    const callsPerItemHistory = probeResolutions.map((r) => r.callsUsed)
    const callsPerItem = Math.max(BATCH_PER_ITEM_FLOOR, trimmedAverage(callsPerItemHistory))
    const projectedTotal = callsPerItem * remainingItems.length * BATCH_SLACK_FACTOR

    // Confirmation gate: a large projection pauses instead of silently spending it, reusing the
    // same needs_approval shape risk-classifier.ts's bulk-reminder gate already established.
    // Probed results are persisted (not discarded) so approving resumes without re-probing, and
    // declining still returns them as real findings.
    if (remainingItems.length > 0 && projectedTotal > BATCH_LARGE_PROJECTION_THRESHOLD) {
      const pendingActionId = crypto.randomUUID()
      const pendingState: BatchPendingState = {
        userMessage,
        systemPrompt,
        sessionId,
        probedResults: probeResolutions,
        remainingItems,
        projectedTotal,
      }
      await this.memory.set(`batch-pending:${pendingActionId}`, pendingState)
      return {
        kind: 'needs_approval',
        reason:
          `This looks like it'll take ~${Math.ceil(projectedTotal)} more searches to cover the remaining ` +
          `${remainingItems.length} item(s) — continue, or should I do a quick pass first?`,
        pendingActionId,
        pendingActionKind: 'batch',
      }
    }

    // Remaining items.
    const { resolutions, notAttempted } = await this.resolveRemainingBatchItems(
      probeResolutions,
      remainingItems,
      systemPrompt,
      sessionId,
      onToolStep,
      onUsage,
      controlPlaneState,
    )
    const content = await this.synthesizeBatchReply(userMessage, systemPrompt, resolutions, notAttempted, onToken, onUsage)
    const sources = resolutions.flatMap((r) => r.sources)
    return { kind: 'final', content, sources, batchBudget: buildBatchBudgetTrace(items.length, projectedTotal, resolutions) }
  }

  /**
   * Dispatches one tool call by name to its executor. web_search/fetch_url results
   * are wrapped as untrusted external content (and flagged if they look like an
   * injection attempt) before they ever reach the model — file and reminder results
   * are not, since they're the assistant's own workspace/state, not adversarial input.
   */
  /** AL8b: optional policy gate for LLM injection detection; `undefined` (default) ⇒ always detect. */
  injectionDetectionGate?: () => boolean
  /** Episodic digest source for `recall_memory` (M3); set by the assistant. The tool is offered only when this is set AND AUDIT_RECALL_TOOL is on. */
  digestReader?: DigestReader
  private recallTools(): ToolDefinition[] {
    return this.digestReader && recallToolEnabled() ? RECALL_TOOLS : []
  }
  /** The opt-in layers' plan for the turn in flight (adaptive mode only), set by the assistant each turn; see resolveOptInPlan. */
  optInPlan?: EscalationPlan

  private async executeToolCall(name: string, input: Record<string, unknown>, userMessage: string, onUsage?: (usage: TokenUsage) => void): Promise<string> {
    if (name === 'read_file' || name === 'list_directory') {
      if (!this.fileTools) throw new Error(`Tool "${name}" called but fileTools is not configured`)
      const result = await executeFileTool(this.fileTools, name, input)
      return result.kind === 'text' ? result.text : ''
    }
    if (name === 'web_search' || name === 'fetch_url') {
      if (!this.webTools) throw new Error(`Tool "${name}" called but webTools is not configured`)
      const result = await executeWebTool(this.webTools, name, input)
      const text = result.kind === 'text' ? result.text : ''
      // AL8b: the layer policy may skip the LLM check only on a non-linguistic proof of safety
      // (injectionDetectionEnabled); no gate installed ⇒ always run, exactly as before.
      const injection = this.injectionDetectionGate && !this.injectionDetectionGate()
        ? { flagged: false, reason: '' }
        : await detectInjectionLikelyWithLLM(text, this.llmClient, this.model(), onUsage)
      const body = injection.flagged
        ? `[Warning: this content contains instruction-like text and may be an injection attempt — ${injection.reason}]\n${text}`
        : text
      return wrapUntrusted(body)
    }
    if (name === 'create_reminder' || name === 'list_reminders') {
      return executeReminderTool(this.reminderStore, name, input, userMessage)
    }
    if (name === 'recall_memory') {
      // Digest text is the assistant's own stored state; the tool wraps it as untrusted itself.
      if (!this.digestReader || !recallToolEnabled()) throw new Error('Tool "recall_memory" called but recall is not enabled')
      return executeRecallTool(this.digestReader, input)
    }
    throw new Error(`Unknown tool: ${name}`)
  }

  /**
   * Trajectory Supervisor GATHER_EVIDENCE host (S5 of
   * the internal plan). A bounded, strictly read-only tool
   * loop the harness calls (via HarnessRunOptions.runInvestigation) when the supervisor
   * decides the run is stuck for lack of a fact.
   *
   * - Read-only only: suggested_tools is filtered through validateInvestigationTools()
   *   (INV-23) and then further to the subset this loop knows how to invoke from just a
   *   question string. write_file / run_shell_command / send_email are never in the
   *   allowlist and executeToolCall() has no branch for them here — no __staged_action
   *   path is reachable.
   * - Its own Budget (INV-25), independent of the turn's batch ceiling: maxCalls =
   *   min(req.budget, allowed tools). Exhaustion returns whatever was found.
   * - Every call is gated by the same evaluateToolPolicy() the manual dispatch loop uses;
   *   a DENY / REQUIRE_APPROVAL skips that tool (an investigation never prompts).
   * - Faults are isolated: a throwing / empty tool call is skipped, never propagated.
   */
  async runSupervisorInvestigation(
    req: InvestigationRequestData,
    opts: { riskHint: RiskLevel; controlState?: Parameters<typeof evaluateToolPolicy>[0]['controlState'] } = {
      riskHint: 'LOW',
    },
  ): Promise<InvestigationFinding[]> {
    const { allowed } = validateInvestigationTools(req.suggested_tools)
    const question = String(req.question ?? '').trim()
    if (!question) return []

    // Budget is immutable — consume() returns a new instance (see state/budget.ts).
    // Shared across every branch below (web/reminder single calls + the workspace walk).
    let budget = new Budget({ maxCalls: Math.max(0, Math.min(req.budget ?? 5, INVESTIGATION_WALK_CAP)) })
    const findings: InvestigationFinding[] = []

    const gated = (tool: string): boolean => {
      const policy = evaluateToolPolicy({ toolName: tool, riskHint: opts.riskHint, controlState: opts.controlState })
      if (policy.decision !== 'ALLOW') {
        this.onTrace?.({ kind: 'layer_activity', layer: 'recovery', fired: false, reason: `investigation: ${tool} skipped — ${policy.reason}` })
        return false
      }
      return true
    }
    const call = async (tool: string, input: Record<string, unknown>): Promise<string> => {
      budget = budget.consume({ calls: 1 })
      try {
        return (await this.executeToolCall(tool, input, question)).trim()
      } catch (err) {
        this.onTrace?.({ kind: 'layer_activity', layer: 'recovery', fired: false, reason: `investigation: ${tool} errored — ${err instanceof Error ? err.message : String(err)}` })
        return ''
      }
    }

    // Single-shot tools we can build from a bare question string.
    for (const tool of allowed) {
      if (budget.isExhausted()) break
      if (tool === 'web_search' && this.webTools && gated('web_search')) {
        const text = await call('web_search', { query: question })
        if (text) findings.push({ content: text.slice(0, 800), tool, reliability: 'MEDIUM' })
      } else if (tool === 'list_reminders' && gated('list_reminders')) {
        const text = await call('list_reminders', {})
        if (text) findings.push({ content: text.slice(0, 800), tool, reliability: 'MEDIUM' })
      }
    }

    // Workspace walk — the question rarely names a path, so a bounded breadth-first
    // read of the sandboxed workspace is how a file-lookup stall gets its missing fact.
    // list_directory can't distinguish a file from a subdir, so each entry is tried as a
    // file first and treated as a directory on failure. Bounded by the shared call
    // budget + INVESTIGATION_WALK_MAX_DEPTH; workspaces in practice are a handful of files.
    const wantsFiles = allowed.includes('read_file') || allowed.includes('list_directory')
    if (wantsFiles && this.fileTools && gated('list_directory') && gated('read_file')) {
      const queue: Array<{ path: string; depth: number }> = [{ path: '.', depth: 0 }]
      const seen = new Set<string>(['.'])
      while (queue.length > 0 && !budget.isExhausted()) {
        const { path, depth } = queue.shift()!
        const listing = await call('list_directory', { path })
        if (!listing) continue
        for (const name of listing.split('\n').map(s => s.trim()).filter(Boolean)) {
          if (budget.isExhausted()) break
          const child = path === '.' ? name : `${path}/${name}`
          if (seen.has(child)) continue
          seen.add(child)
          const content = await call('read_file', { path: child })
          if (content) {
            findings.push({ content: `${child}:\n${content}`.slice(0, 800), tool: 'read_file', reliability: 'MEDIUM' })
          } else if (depth + 1 < INVESTIGATION_WALK_MAX_DEPTH) {
            queue.push({ path: child, depth: depth + 1 })
          }
        }
      }
    }

    return findings
  }
}

