export function formatHelp(): string {
  const width = Math.max(...CLI_COMMANDS_HELP.map((c) => c.command.length))
  return CLI_COMMANDS_HELP.map((c) => `  ${c.command.padEnd(width + 2)} ${c.description}`).join('\n')
}

export interface StatusInfo {
  config: AssistantConfig
  overriddenKeys: ReadonlySet<keyof AssistantConfig>
  transcriptLength: number
  planActive: boolean
  /** Real filesystem effects still on record as revertible (see action-snapshot.ts) — omitted entirely when no workspace is configured (fileTools/shellTools both absent), same "don't imply a capability that isn't there" rule the banner's capability list already follows. */
  undoLogEntries?: UndoLogEntry[]
  /** Pre-formatted by spend-cap.ts's formatSpendCapStatus — undefined when no ceiling is configured, in which case the line is omitted entirely. */
  spendCapLine?: string
}

/** Reuses formatConfigListing for the config half rather than re-formatting the same fields a second way. */
export function formatStatus(info: StatusInfo): string {
  const lines = [
    formatConfigListing(info.config, info.overriddenKeys),
    '',
    `  ${'transcript'.padEnd(14)} ${info.transcriptLength} message${info.transcriptLength === 1 ? '' : 's'} this session`,
    `  ${'active plan'.padEnd(14)} ${info.planActive ? 'yes (see /plan)' : 'none'}`,
  ]
  if (info.undoLogEntries !== undefined) {
    const total = info.undoLogEntries.length
    const undoable = info.undoLogEntries.filter((e) => e.undoable).length
    lines.push(
      `  ${'undo-log'.padEnd(14)} ${total} entr${total === 1 ? 'y' : 'ies'} (${undoable} revertible) — see /undo-action`,
    )
  }
  if (info.spendCapLine) {
    lines.push(`  ${'spend cap'.padEnd(14)} ${info.spendCapLine}`)
  }
  return lines.join('\n')
}

const CATEGORY_LABELS: Record<FactCategory, string> = {
  identity: 'Identity',
  health: 'Health',
  preference: 'Preference',
  location: 'Location',
  occupation: 'Occupation',
  relationships: 'Relationships',
  project: 'Project',
  other: 'Other',
}

/** One "Facts I know" line — text plus its metadata chips (topic, certainty, established date, and, for a project-scoped fact, which project) so /memory reads as a real inventory rather than a flat, unlabeled list. Certainty always shows via certaintyLabel() (see its doc comment on why an inherently-certain user_asserted fact still gets a label); category/project are omitted when absent rather than shown as "none". */
function formatFactLine(f: UserFact): string {
  const chips: string[] = []
  if (f.category) chips.push(CATEGORY_LABELS[f.category].toLowerCase())
  chips.push(`${certaintyLabel(f)} certainty`)
  chips.push(`established ${f.extractedAt.slice(0, 10)}`)
  if (f.project) chips.push(`project: ${f.project}`)
  return `${f.text} (${chips.join(', ')})`
}

/**
 * `/memory`'s "Pending confirmation" section — Phase 3 of
 * the internal plan. Grouped by category (so a
 * topic that accumulated several related guesses reads as one group, not scattered numbers) but
 * numbered in one flat, display-order sequence across every group — `/memory confirm <n>`/
 * `/memory reject <n>` take that same 1-based number, not a per-category one.
 */
function formatPendingConfirmation(pending: PendingFact[]): string {
  const lines = ['\nPending confirmation:']
  if (pending.length === 0) {
    lines.push('  None')
    return lines.join('\n')
  }
  const byCategory = new Map<FactCategory, { fact: PendingFact; n: number }[]>()
  pending.forEach((fact, i) => {
    const group = byCategory.get(fact.category) ?? []
    group.push({ fact, n: i + 1 })
    byCategory.set(fact.category, group)
  })
  for (const [category, entries] of byCategory) {
    lines.push(`  ${CATEGORY_LABELS[category]}:`)
    for (const { fact, n } of entries) {
      const suffix = fact.flagged ? ' (flagged: reads like an instruction — review before confirming)' : fact.previouslyRejected ? ' (previously rejected — restated)' : ''
      const reviewerNote = fact.stagedBy === 'reviewer' ? ` (proposed by the memory reviewer${fact.verification === 'not_checked' ? ', not independently checked' : ''})` : ''
      const head = fact.proposedOp === 'retire' ? `Retire: ${fact.text}` : fact.text
      lines.push(`    ${n}. ${head}${suffix}${reviewerNote}`)
      if (fact.stagedBy === 'reviewer' && fact.evidence) lines.push(`       you said: "${fact.evidence}"`)
    }
  }
  lines.push('  Use /memory confirm <n|category> or /memory reject <n|category>.')
  return lines.join('\n')
}

/** Renders the result of `/memory confirm`/`/memory reject` — cli.ts's handleMemoryConfirm/handleMemoryReject print this directly. */
export function formatMemoryPendingOutcome(action: 'confirmed' | 'rejected' | 'forgotten', outcome: MemoryPendingOutcome): string {
  if (!outcome.ok) return `✗ ${outcome.error}`
  const lines = outcome.facts.map((f) => `✓ ${action}: ${f.text}`)
  for (const notice of outcome.conflictNotices) {
    lines.push(`  ⚠ ${notice}`)
  }
  return lines.join('\n')
}

export function formatMemorySummary(summary: MemorySummary): string {
  const sections: string[] = []

  sections.push('Facts I know:')
  sections.push(
    summary.facts.length > 0
      ? [...summary.facts.map((f, i) => `  ${i + 1}. ${formatFactLine(f)}`), '  Use /memory forget <n> to remove one.'].join('\n')
      : '  None yet',
  )

  sections.push('\nReminders:')
  sections.push(
    summary.reminders.length > 0
      ? summary.reminders.map((r) => `  - ${r.rawText}${r.done ? ' (done)' : ''}`).join('\n')
      : '  None yet',
  )

  sections.push(formatPendingConfirmation(summary.pending))

  const strategyWeightEntries = Object.entries(summary.experience.strategyWeights)
  sections.push('\nStrategy weights:')
  sections.push(
    strategyWeightEntries.length > 0
      ? strategyWeightEntries.map(([key, weight]) => `  - ${key}: ${weight.toFixed(3)}`).join('\n')
      : '  None yet',
  )

  sections.push('\nLearned decompositions (most recent, up to 20):')
  sections.push(
    summary.experience.decompositions.length > 0
      ? summary.experience.decompositions
          .map((d) => `  - ${d.task_type}: ${d.decomposition.join(' → ')} (${(d.success_rate * 100).toFixed(0)}% success)`)
          .join('\n')
      : '  None yet',
  )

  sections.push('\nRecovery sequences (most recent, up to 20):')
  sections.push(
    summary.experience.recoverySequences.length > 0
      ? summary.experience.recoverySequences
          .map((r) => `  - ${r.failure_class}: ${r.strategy_sequence.join(' → ')} (${(r.success_rate * 100).toFixed(0)}% success)`)
          .join('\n')
      : '  None yet',
  )

  return sections.join('\n')
}

/** `/memory history` — one line per audit entry. */
export function formatMemoryHistory(entries: AuditEntry[]): string {
  if (entries.length === 0) return 'No memory changes recorded (the audit log is empty or AUDIT_MEMORY_AUDIT_LOG is off).'
  return entries
    .map((e) => `#${e.seq} ${e.at} ${e.op} [${e.store}] ${e.erased ? '(erased by you)' : (e.after ?? e.before)?.text ?? e.factId} (${e.writer})`)
    .join('\n')
}

/** `/memory archive` — facts a newer keyed statement replaced. */
export function formatMemoryArchive(facts: UserFact[], restorableCount = 0): string {
  if (facts.length === 0) return 'Archive is empty.'
  return [...facts.map((f, i) => `  ${i + 1}. ${f.text} (${i < restorableCount ? 'set aside' : 'replaced'} ${f.retiredAt?.slice(0, 10) ?? 'earlier'})`), '  Use /memory archive restore <n> to bring a set-aside one back, or /memory archive forget <n> to erase one for good.'].join('\n')
}

/** The "Why?" / `/why` line: which stored facts the last reply could have known, and how many were left out. Says "in the prompt", not "used". */
export function formatMemoryInjection(injection: MemoryInjection | undefined): string {
  if (!injection) return 'No turn has run yet, so no memory has been put in front of the model.'
  const n = injection.facts.length
  const head = `Memory in the prompt: ${n} fact${n === 1 ? '' : 's'}${injection.notShown > 0 ? `; ${injection.notShown} not shown this turn` : ''}.`
  return [head, ...injection.facts.map((f) => `  - ${f.text}${f.unconfirmed ? ' (unconfirmed)' : ''}`)].join('\n')
}

const MODE_LABEL: Record<MemoryStatus['mode'], string> = {
  auto: 'auto (cross-turn writers may save directly)',
  staged: 'staged (cross-turn writers wait for your confirmation)',
  user_only: 'user_only (the model never saves a fact on its own)',
}

/** `/memory status` and the memory panel header. */
export function formatMemoryStatus(status: MemoryStatus): string {
  const lines = [
    `Writes: ${status.off ? 'OFF (/memory on to resume)' : 'on'}  ·  mode: ${MODE_LABEL[status.mode]}`,
    `Store: ${status.liveFacts} fact${status.liveFacts === 1 ? '' : 's'}, ${status.storeChars}/${status.budgetChars} chars${status.budgetedRender ? '' : ' (budget not enforced: AUDIT_MEMORY_BUDGETED_RENDER is off)'}`,
    `Pending: ${status.pending}${status.flaggedPending > 0 ? ` (${status.flaggedPending} flagged)` : ''}  ·  replaced/archived: ${status.retired}  ·  history: ${status.auditEnabled ? `${status.auditEntries} entries` : 'off'}`,
    `Last consolidation: ${status.lastConsolidatedSeq !== undefined ? `through #${status.lastConsolidatedSeq}${status.lastConsolidationAt ? ` at ${status.lastConsolidationAt}` : ''}` : 'never'}`,
  ]
  if (status.lastInjection && status.lastInjection.notShown > 0) lines.push(`${status.lastInjection.notShown} fact${status.lastInjection.notShown === 1 ? '' : 's'} not shown last turn`)
  return lines.join('\n')
}

/** `/doctor` entries for memory (CLI via doctor-checks.ts, chat-ui directly — same pure function on both surfaces). */
export function memoryStatusChecks(status: MemoryStatus): DoctorCheck[] {
  const overBudget = status.budgetedRender && status.storeChars > status.budgetChars
  return [
    { label: `memory store: ${status.liveFacts} facts, ${status.storeChars}/${status.budgetChars} chars`, ok: !overBudget, detail: overBudget ? 'over budget: some facts are not shown each turn; consolidate or forget some' : undefined },
    { label: `memory pending: ${status.pending}${status.flaggedPending > 0 ? ` (${status.flaggedPending} flagged)` : ''}`, ok: status.flaggedPending === 0, detail: status.flaggedPending > 0 ? 'review flagged items with /memory' : undefined },
    { label: `memory last consolidation: ${status.lastConsolidatedSeq !== undefined ? `through audit #${status.lastConsolidatedSeq}` : 'never'}`, ok: true },
    { label: `memory audit log: ${status.auditEnabled ? `${status.auditEntries} entries` : 'off'}, writes ${status.off ? 'OFF' : 'on'}, mode ${status.mode}`, ok: true },
  ]
}

/** Renders `/memory export`'s full, unbounded contents as pretty-printed JSON — a plain formatting function so it's unit-testable the same way as every other cli-session.ts formatter; cli.ts does the actual file write. */
export function formatMemoryExport(data: MemoryExport): string {
  return JSON.stringify(data, null, 2)
}

/** Truncates `content` to a snippet around the first matching term when possible, else the leading `maxLen` chars — full messages can be long, and a search result list is meant to be scannable, not a second transcript view. */
function snippet(content: string, query: string, maxLen = 160): string {
  const normalized = content.replace(/\s+/g, ' ').trim()
  if (normalized.length <= maxLen) return normalized
  const firstTerm = query.split(/\s+/).find((t) => t.length > 0)
  const matchAt = firstTerm ? normalized.toLowerCase().indexOf(firstTerm.toLowerCase()) : -1
  if (matchAt === -1) return `${normalized.slice(0, maxLen)}…`
  const start = Math.max(0, matchAt - maxLen / 2)
  const end = Math.min(normalized.length, start + maxLen)
  return `${start > 0 ? '…' : ''}${normalized.slice(start, end)}${end < normalized.length ? '…' : ''}`
}

/** Renders `/search <query>`'s results — each hit is one message (session id short form, timestamp, role, snippet), ranked by relevance, never the whole session it came from. An empty list is an explicit "no results" line, never a silent blank output. */
export function formatSearchResults(hits: TranscriptSearchHit[], query: string): string {
  if (hits.length === 0) return `No results for "${query}".`
  return hits
    .map((h) => {
      const shortSession = h.sessionId.length > 8 ? `${h.sessionId.slice(0, 8)}…` : h.sessionId
      return `  [${shortSession}] ${h.at}  ${h.role.padEnd(9)} ${snippet(h.content, query)}`
    })
    .join('\n')
}

const VISIBILITY_LABEL: Record<GoalThreadVisibility, string> = {
  suggested_not_committed: 'suggested, not committed',
  done: 'done',
  freshly_computed: 'freshly computed',
  carried_over: 'carried over',
}

function formatGoalThreadLine(thread: GoalThreadView): string {
  const focus = thread.isActive ? ' [ACTIVE]' : ''
  const sibling = thread.relationToSiblings ? ` (${thread.relationToSiblings} sibling${thread.siblingIds && thread.siblingIds.length > 1 ? 's' : ''})` : ''
  const { total, complete, failed, pending } = thread.tasks
  const taskLine = total > 0 ? `tasks: ${complete}/${total} complete${failed > 0 ? `, ${failed} failed` : ''}${pending > 0 ? `, ${pending} pending` : ''}` : 'no tasks yet'
  const suggestions = (thread.suggestions ?? []).map((sg) => `    next step (suggested, not committed) [${sg.confidence}]: ${sg.description}`)
  return [
    `  [${thread.status}]${focus} ${thread.successCriteria}${sibling}`,
    `    visibility: ${VISIBILITY_LABEL[thread.visibility]}  ·  ${taskLine}  ·  updated ${thread.updatedAt}`,
    ...suggestions,
  ].join('\n')
}

/** Renders the turn-end next-step options shown under a full turn's reply — numbered so the CLI can accept a bare `1`/`2`/`3` as "run that one" (see cli.ts's dispatchOne). Only the description is shown; the rationale and confidence stay in the structured result for richer front ends. */
export function formatNextSteps(steps: NextStepSuggestion[]): string {
  return ['Next steps you could take (type 1, 2 or 3 to run one — or just type your own message):', ...steps.map((s, i) => `  ${i + 1}. ${s.description}`)].join('\n')
}

/**
 * Renders `/goals`' review surface (R5, "Visibility") — every known GoalThread this session, each
 * tagged with which of R5's four visibility buckets it falls in
 * (freshly-computed/carried-over/done/suggested-but-not-committed), so a user can tell live state
 * apart from stale carryover without re-deriving it from raw JSON. An empty graph is an explicit
 * line, same convention `formatSearchResults` follows for zero hits.
 */
export function formatGoalGraphState(state: GoalGraphState): string {
  if (state.threads.length === 0) return 'No goal threads yet.'
  return state.threads.map((t) => formatGoalThreadLine(t)).join('\n\n')
}

function undoLogEntryLabel(entry: UndoLogEntry): string {
  return entry.kind === 'write' ? `write "${entry.path}"` : `shell \`${entry.command}\``
}

/** Renders /undo-action's no-argument listing — newest first (see action-snapshot.ts's listUndoLogEntries), with each entry's undoable status so the user doesn't have to stage a revert just to find out it's unavailable. */
export function formatUndoLogListing(entries: UndoLogEntry[]): string {
  if (entries.length === 0) return 'No undo-log entries yet — nothing to revert.'
  return entries
    .map((e) => {
      const status = e.undoable ? 'undoable' : `NOT undoable — ${e.reason}`
      return `  ${e.id}  ${undoLogEntryLabel(e)}  (${e.appliedAt})  [${status}]`
    })
    .join('\n')
}

/** Renders a transcript as markdown for /export — "You:"/"Assistant:" turns, oldest first. */
export function formatTranscriptMarkdown(transcript: ChatMessage[]): string {
  return transcript
    .filter((m) => m.role === 'user' || m.role === 'assistant')
    .map((m) => `**${m.role === 'user' ? 'You' : 'Assistant'}:** ${m.content}`)
    .join('\n\n')
}

/** Default /export filename when none is given — mirrors Claude Code's own /export default-name convention. Colons/dots are filesystem-unsafe on some platforms, so the ISO timestamp is sanitized. */
export function defaultExportFilename(now: Date = new Date()): string {
  return `assistant-transcript-${now.toISOString().replace(/[:.]/g, '-')}.md`
}

/** Default /memory export filename when none is given — same sanitized-ISO-timestamp convention as defaultExportFilename, JSON instead of markdown. */
export function defaultMemoryExportFilename(now: Date = new Date()): string {
  return `assistant-memory-${now.toISOString().replace(/[:.]/g, '-')}.json`
}

export interface CostSummaryInfo {
  /** Usage for the turn just completed — absent when the last turn reported no usage at all, or no turn has completed yet. */
  lastTurn?: TokenUsage
  /** Running total across the session — {inputTokens: 0, outputTokens: 0} before any usage has ever been reported. */
  session: TokenUsage
  backend: 'proxy' | 'claude-cli' | 'anthropic' | 'openai' | 'openrouter'
  /** Pre-formatted by spend-cap.ts's formatSpendCapStatus — undefined when no ceiling is configured, in which case the line is omitted entirely (same convention as StatusInfo.spendCapLine). */
  spendCapLine?: string
}

function formatUsageLine(usage: TokenUsage): string {
  const tokens = `${usage.inputTokens.toLocaleString()} in / ${usage.outputTokens.toLocaleString()} out tokens`
  return usage.costUsd !== undefined ? `${tokens}  (~$${usage.costUsd.toFixed(4)})` : tokens
}

/** Renders /cost's output. The backend-specific footnote matters: claude-cli's cost is real (but may read $0 on a Pro/Max subscription, not API billing); every other backend's cost, when shown, is a static-table estimate (see cli.ts's withCostEstimate), never real billing data — see model-pricing.ts. */
export function formatCostSummary(info: CostSummaryInfo): string {
  if (!info.lastTurn && info.session.inputTokens === 0 && info.session.outputTokens === 0 && !info.spendCapLine) {
    return 'No usage yet this session.'
  }
  const lines: string[] = []
  if (info.lastTurn) lines.push(`Last turn:    ${formatUsageLine(info.lastTurn)}`)
  lines.push(`This session: ${formatUsageLine(info.session)}`)
  if (info.backend === 'claude-cli') {
    lines.push('(cost is real usage from your Claude Code session — may read $0 on a Pro/Max subscription rather than API billing)')
  } else if (info.session.costUsd !== undefined) {
    lines.push('(cost is an approximate estimate from a static pricing table, not real billing data)')
  }
  if (info.spendCapLine) lines.push(`Session ceiling: ${info.spendCapLine}`)
  return lines.join('\n')
}

export interface DoctorCheck {
  label: string
  ok: boolean
  /** Failure reason ("timed out", "not found", an HTTP status, etc.) — omitted entirely on a passing check. */
  detail?: string
}

/** Renders /doctor's ✓/✗ list — the actual checks (network fetch, subprocess spawn, filesystem stat) run in cli.ts, which has the I/O; this just formats the results. */
export function formatDoctorReport(checks: DoctorCheck[]): string {
  return checks.map((c) => `  ${c.ok ? '✓' : '✗'} ${c.label}${!c.ok && c.detail ? ` — ${c.detail}` : ''}`).join('\n')
}
